/home/diogenes/Projects/keating/web/src/keating/nodepod-boot-files.ts:84:  "src/core/export.ts": "import { mkdir, readdir, readFile, stat, writeFile } from \"node:fs/promises\";\nimport { basename, extname, join, relative } from \"node:path\";\n\nimport {\n  benchmarksDir,\n  evolutionDir,\n  exportsDir,\n  improvementsDir,\n  mapsDir,\n  plansDir,\n  promptEvolutionDir,\n  quizDir,\n  sessionsDir,\n  tracesDir,\n  verificationsDir\n} from \"./paths.js\";\nimport { slugify } from \"./util.js\";\nimport { cliSourceHash, cliSourceMessages, loadCliLearnerEvents, type CliSourceMessage } from \"./learner-events.js\";\nimport { computeCliRewardedTurns, type CliRewardedTurn, type CliQuizWithTiming } from \"./session-reward.js\";\nimport { loadCliQuizRecord } from \"./quiz-grading.js\";\n\nexport type ExportMode = \"finetune\";\nexport type ExportSource = \"all\" | \"artifacts\" | \"sessions\";\nexport type FineTuneFormat = \"chatml\" | \"alpaca\" | \"both\";\n\nexport interface KeatingExportOptions {\n  mode: ExportMode;\n  source: ExportSource;\n  format: FineTuneFormat;\n  outDir?: string;\n  redact: boolean;\n  minAssistantChars: number;\n}\n\nexport interface KeatingExportManifest {\n  schemaVersion: 1;\n  mode: ExportMode;\n  generatedAt: string;\n  source: ExportSource;\n  format: FineTuneFormat;\n  counts: {\n    artifactsRead: number;\n    sessionsRead: number;\n    examplesWritten: number;\n    skipped: number;\n    redactions: number;\n    rewardedTurns?: number;\n    scoredTurns?: number;\n  };\n  files: string[];\n  warnings: string[];\n}\n\ninterface FineTuneExample {\n  id: string;\n  source: \"artifact\" | \"session\";\n  kind: string;\n  instruction: string;\n  input?: string;\n  output: string;\n  messages?: Array<{ role: \"user\" | \"assistant\"; content: string }>;\n}\n\n/**\n * One ChatML JSONL line = one conversation. Sessions become a single full\n * multi-turn conversation (system turns preserved) carrying a `keating`\n * envelope so the importer can reconstruct a faithful, resumable session;\n * lossless exports (redaction off) also embed the original full messages.\n */\ninterface FineTuneConversation {\n  source: \"artifact\" | \"session\";\n  messages: Array<{ role: \"system\" | \"user\" | \"assistant\"; content: string }>;\n  envelope?: {\n    title?: string;\n    sessionId?: string;\n    source?: string;\n    model?: unknown;\n    thinkingLevel?: string;\n    messages?: unknown[];\n  };\n}\n\ninterface BuildResult {\n  rewardedTurns: CliRewardedTurn[];\n  examples: FineTuneExample[];\n  conversations: FineTuneConversation[];\n  corpusSections: string[];\n  artifactsRead: number;\n  sessionsRead: number;\n  skipped: number;\n  redactions: number;\n  warnings: string[];\n}\n\nfunction createBuildResult(): BuildResult {\n  return {\n    rewardedTurns: [],\n    examples: [],\n    conversations: [],\n    corpusSections: [],\n    artifactsRead: 0,\n    sessionsRead: 0,\n    skipped: 0,\n    redactions: 0,\n    warnings: [],\n  };\n}\n\nconst DEFAULT_OPTIONS: KeatingExportOptions = {\n  mode: \"finetune\",\n  source: \"all\",\n  format: \"both\",\n  redact: true,\n  minAssistantChars: 80,\n};\n\nconst SECRET_PATTERNS: RegExp[] = [\n  /\\bsk-ant-[A-Za-z0-9_-]{12,}\\b/g,\n  /\\bsk-[A-Za-z0-9_-]{12,}\\b/g,\n  /\\bAIza[A-Za-z0-9_-]{16,}\\b/g,\n  /\\bghp_[A-Za-z0-9_]{12,}\\b/g,\n  /\\bBearer\\s+[A-Za-z0-9._-]{12,}\\b/gi,\n  /^[A-Z][A-Z0-9_]*_API_KEY\\s*=\\s*.+$/gm,\n  /\\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}\\b/gi,\n];\n\nconst FINETUNE_TEMPLATE_DIR = new URL(\"./templates/finetune/\", import.meta.url);\n\nasync function readFineTuneTemplate(path: string): Promise<string> {\n  return readFile(new URL(path, FINETUNE_TEMPLATE_DIR), \"utf8\");\n}\n\nfunction normalizeOptions(options: KeatingExportOptions): KeatingExportOptions {\n  return {\n    ...DEFAULT_OPTIONS,\n    ...options,\n    minAssistantChars: Math.max(1, Math.floor(options.minAssistantChars || DEFAULT_OPTIONS.minAssistantChars)),\n  };\n}\n\nfunction redactText(input: string, enabled: boolean): { text: string; count: number } {\n  if (!enabled) return { text: input, count: 0 };\n  let text = input;\n  let count = 0;\n  for (const pattern of SECRET_PATTERNS) {\n    text = text.replace(pattern, () => {\n      count += 1;\n      return \"[REDACTED]\";\n    });\n  }\n  return { text, count };\n}\n\nasync function collectFiles(root: string): Promise<string[]> {\n  const entries = await readdir(root, { withFileTypes: true }).catch(() => []);\n  const files: string[] = [];\n  for (const entry of entries) {\n    const full = join(root, entry.name);\n    if (entry.isDirectory()) {\n      files.push(...await collectFiles(full));\n    } else if (entry.isFile()) {\n      files.push(full);\n    }\n  }\n  return files.sort();\n}\n\nfunction titleFromPath(path: string): string {\n  return basename(path, extname(path)).replace(/-/g, \" \");\n}\n\nfunction artifactInstruction(kind: string, topic: string): string {\n  switch (kind) {\n    case \"plan\":\n      return `Create a Keating-style Socratic lesson plan for ${topic}.`;\n    case \"quiz\":\n      return `Create retrieval practice and an answer key for ${topic}.`;\n    case \"map\":\n      return `Create a Mermaid concept map for ${topic}.`;\n    case \"verification\":\n      return `Create a verification checklist before teaching ${topic}.`;\n    default:\n      return `Create a Keating teaching artifact for ${topic}.`;\n  }\n}\n\nfunction parseMessageText(message: any): string {\n  const content = message?.content;\n  if (typeof content === \"string\") return content;\n  if (!Array.isArray(content)) return \"\";\n  return content.map((part) => {\n    if (typeof part === \"string\") return part;\n    if (part?.type === \"text\" && typeof part.text === \"string\") return part.text;\n    if (typeof part?.text === \"string\") return part.text;\n    if (part?.type === \"file\" && typeof part.filename === \"string\") return `[Attachment: ${part.filename}]`;\n    return \"\";\n  }).filter(Boolean).join(\"\\n\");\n}\n\nfunction isBadAssistantText(text: string, message: any): boolean {\n  if (message?.stopReason === \"error\") return true;\n  return /__KEATING_ERROR__|authentication failed|no api key|stack trace|^\\s*error:/i.test(text);\n}\n\nfunction sessionExamplesFromMessages(\n  sessionId: string,\n  messages: any[],\n  options: KeatingExportOptions\n): { examples: FineTuneExample[]; skipped: number; redactions: number; corpus: string } {\n  const chatMessages: Array<{ role: \"user\" | \"assistant\"; content: string }> = [];\n  let skipped = 0;\n  let redactions = 0;\n\n  for (const message of messages) {\n    const rawRole = message?.role;\n    const role = rawRole === \"user\" || rawRole === \"user-with-attachments\"\n      ? \"user\"\n      : rawRole === \"assistant\"\n        ? \"assistant\"\n        : null;\n    if (!role) {\n      skipped += 1;\n      continue;\n    }\n    const rawText = parseMessageText(message).trim();\n    if (!rawText) {\n      skipped += 1;\n      continue;\n    }\n    if (role === \"assistant\" && isBadAssistantText(rawText, message)) {\n      skipped += 1;\n      continue;\n    }\n    if (role === \"assistant\" && rawText.length < options.minAssistantChars) {\n      skipped += 1;\n      continue;\n    }\n    const redacted = redactText(rawText, options.redact);\n    redactions += redacted.count;\n    chatMessages.push({ role, content: redacted.text });\n  }\n\n  const examples: FineTuneExample[] = [];\n  let pairIndex = 0;\n  for (let i = 0; i < chatMessages.length - 1; i += 1) {\n    const user = chatMessages[i];\n    const assistant = chatMessages[i + 1];\n    if (user?.role !== \"user\" || assistant?.role !== \"assistant\") continue;\n    examples.push({\n      id: `session-${slugify(sessionId)}-${pairIndex++}`,\n      source: \"session\",\n      kind: \"conversation\",\n      instruction: user.content,\n      output: assistant.content,\n      messages: [user, assistant],\n    });\n  }\n\n  const corpus = chatMessages.length\n    ? [`## Session ${sessionId}`, ...chatMessages.map((m) => `**${m.role}:** ${m.content}`)].join(\"\\n\\n\")\n    : \"\";\n  return { examples, skipped, redactions, corpus };\n}\n\nasync function buildArtifactExamples(cwd: string, options: KeatingExportOptions): Promise<BuildResult> {\n  const result = createBuildResult();\n\n  const artifactRoots = [\n    { kind: \"plan\", root: plansDir(cwd), include: (path: string) => path.endsWith(\".md\") },\n    { kind: \"quiz\", root: quizDir(cwd), include: (path: string) => path.endsWith(\".md\") },\n    { kind: \"map\", root: mapsDir(cwd), include: (path: string) => path.endsWith(\".mmd\") },\n    { kind: \"verification\", root: verificationsDir(cwd), include: (path: string) => path.endsWith(\".md\") },\n  ];\n\n  for (const { kind, root, include } of artifactRoots) {\n    for (const file of (await collectFiles(root)).filter(include)) {\n      const raw = await readFile(file, \"utf8\").catch(() => \"\");\n      result.artifactsRead += 1;\n      if (!raw.trim()) {\n        result.skipped += 1;\n        continue;\n      }\n      const topic = titleFromPath(file).replace(/\\s+answers$/i, \"\");\n      const redacted = redactText(raw.trim(), options.redact);\n      result.redactions += redacted.count;\n      result.examples.push({\n        id: `${kind}-${slugify(relative(cwd, file))}`,\n        source: \"artifact\",\n        kind,\n        instruction: artifactInstruction(kind, topic),\n        output: redacted.text,\n        messages: [\n          { role: \"user\", content: artifactInstruction(kind, topic) },\n          { role: \"assistant\", content: redacted.text },\n        ],\n      });\n      result.conversations.push({\n        source: \"artifact\",\n        messages: [\n          { role: \"user\", content: artifactInstruction(kind, topic) },\n          { role: \"assistant\", content: redacted.text },\n        ],\n      });\n      result.corpusSections.push(`## ${kind}: ${relative(cwd, file)}\\n\\n${redacted.text}`);\n    }\n  }\n\n  for (const root of [benchmarksDir(cwd), evolutionDir(cwd), promptEvolutionDir(cwd), improvementsDir(cwd), tracesDir(cwd)]) {\n    for (const file of await collectFiles(root)) {\n      const info = await stat(file).catch(() => null);\n      if (!info || info.size > 512_000) continue;\n      const raw = await readFile(file, \"utf8\").catch(() => \"\");\n      if (raw.trim()) {\n        const redacted = redactText(raw.trim(), options.redact);\n        result.redactions += redacted.count;\n        result.corpusSections.push(`## Reference: ${relative(cwd, file)}\\n\\n${redacted.text}`);\n      }\n    }\n  }\n\n  return result;\n}\n\n/** Builds one full, resumable conversation from a session's raw messages. */\nfunction conversationFromSession(\n  parsed: any,\n  sessionId: string,\n  messages: any[],\n  options: KeatingExportOptions,\n): { conversation: FineTuneConversation | null; redactions: number } {\n  const turns: FineTuneConversation[\"messages\"] = [];\n  let redactions = 0;\n  for (const message of messages) {\n    const rawRole = message?.role;\n    const role = rawRole === \"user\" || rawRole === \"user-with-attachments\"\n      ? \"user\"\n      : rawRole === \"assistant\"\n        ? \"assistant\"\n        : rawRole === \"system\"\n          ? \"system\"\n          : null;\n    if (!role) continue;\n    const text = parseMessageText(message).trim();\n    if (!text) continue;\n    // Keep the visible training turns at the same quality bar as the paired\n    // examples (drop error/too-short assistant turns); the lossless envelope\n    // below still carries the unfiltered originals for faithful resume.\n    if (role === \"assistant\" && isBadAssistantText(text, message)) continue;\n    if (role === \"assistant\" && text.length < options.minAssistantChars) continue;\n    const redacted = redactText(text, options.redact);\n    redactions += redacted.count;\n    turns.push({ role, content: redacted.text });\n  }\n  const hasUser = turns.some((turn) => turn.role === \"user\");\n  const hasAssistant = turns.some((turn) => turn.role === \"assistant\");\n  if (!hasUser || !hasAssistant) return { conversation: null, redactions };\n  return {\n    conversation: {\n      source: \"session\",\n      messages: turns,\n      envelope: {\n        title: typeof parsed?.title === \"string\" ? parsed.title : undefined,\n        sessionId,\n        source: \"keating-session-export\",\n        model: parsed?.model && typeof parsed.model === \"object\" ? parsed.model : undefined,\n        thinkingLevel: typeof parsed?.thinkingLevel === \"string\" ? parsed.thinkingLevel : undefined,\n        // Lossless resume: embed original messages only when not redacting.\n        messages: options.redact ? undefined : messages,\n      },\n    },\n    redactions,\n  };\n}\n\nasync function buildSessionExamples(cwd: string, options: KeatingExportOptions): Promise<BuildResult> {\n  const result = createBuildResult();\n\n  for (const file of (await collectFiles(sessionsDir(cwd))).filter((path) => /\\.jsonl?$/.test(path))) {\n    const raw = await readFile(file, \"utf8\").catch(() => \"\");\n    if (!raw.trim()) continue;\n    try {\n      let parsed: any;\n      let sourceMessages: CliSourceMessage[];\n      if (file.endsWith(\".jsonl\")) {\n        // Use Pi's branch semantics instead of flattening alternate histories.\n        const { SessionManager } = await import(\"@earendil-works/pi-coding-agent\");\n        const session = SessionManager.open(file);\n        const branch = session.getBranch();\n        sourceMessages = cliSourceMessages(branch);\n        parsed = { id: session.getSessionId(), title: session.getSessionName(),\n          // Pi has hidden reasoning, tool arguments and tool results in its\n          // native transcript. New exports expose visible text only.\n          messages: sourceMessages };\n      } else {\n        parsed = JSON.parse(raw);\n        const saved = Array.isArray(parsed?.messages) ? parsed.messages : Array.isArray(parsed) ? parsed : [];\n        sourceMessages = cliSourceMessages(saved.map((message: any, index: number) => ({ type: \"message\",\n          id: typeof message.id === \"string\" && /^[A-Za-z0-9_-]{1,200}$/.test(message.id) ? message.id : `unbound-${index}`,\n          timestamp: message.timestamp, message })));\n      }\n      const messages = Array.isArray(parsed?.messages) ? parsed.messages : Array.isArray(parsed) ? parsed : [];\n      if (!messages.length) {\n        result.skipped += 1;\n        continue;\n      }\n      result.sessionsRead += 1;\n      const sessionId = typeof parsed?.id === \"string\" ? parsed.id : basename(file, \".json\");\n      const converted = sessionExamplesFromMessages(sessionId, messages, options);\n      result.examples.push(...converted.examples);\n      result.skipped += converted.skipped;\n      result.redactions += converted.redactions;\n      if (converted.corpus) result.corpusSections.push(converted.corpus);\n      // One full, resumable conversation per session for the ChatML output.\n      // (Redaction counts come from the example path above to avoid double counting.)\n      const conv = conversationFromSession(parsed, sessionId, messages, options);\n      if (conv.conversation) result.conversations.push(conv.conversation);\n      // Legacy imports lacking stable IDs still export normally, but cannot\n      // acquire proxy rewards from unrelated learner-state timestamp matches.\n      if (!sourceMessages.length) sourceMessages = messages.flatMap((message: any, index: number) =>\n        [\"user\", \"assistant\"].includes(message?.role) && parseMessageText(message).trim()\n          ? [{ id: `unbound-${index}`, role: message.role, content: parseMessageText(message) }] : []);\n      let rewards: CliRewardedTurn[];\n      try {\n        rewards = await rewardedSessionTurns(cwd, sessionId, sourceMessages);\n      } catch {\n        result.warnings.push(`Reward evidence unavailable for session: ${sessionId}`);\n        rewards = computeCliRewardedTurns({ sessionId, messages: sourceMessages.map(message => ({ ...message, timestamp: undefined })), feedback: [], quizResults: [] });\n      }\n      for (const turn of rewards) {\n        if (turn.completion.trim().length < options.minAssistantChars || isBadAssistantText(turn.completion, {})) continue;\n        result.rewardedTurns.push({ ...turn,\n          completion: redactText(turn.completion, options.redact).text,\n          context: turn.context.map(message => ({ ...message, content: redactText(message.content, options.redact).text })),\n        });\n      }\n    } catch {\n      result.warnings.push(`Skipped invalid session JSON: ${relative(cwd, file)}`);\n      result.skipped += 1;\n    }\n  }\n\n  return result;\n}\n\n/** Source-bound event facts only; no heuristic joins against project-wide state. */\nasync function rewardedSessionTurns(cwd: string, sessionId: string, messages: CliSourceMessage[]): Promise<CliRewardedTurn[]> {\n  const events = await loadCliLearnerEvents(cwd, sessionId);\n  const bound = messages.map(message => {\n    const source = events.find(event => event.kind === \"message\" && event.messageId === message.id\n      && event.role === message.role && event.contentSha256 === cliSourceHash(message.content)\n      && event.timestamp === message.timestamp);\n    return { ...message, timestamp: source ? message.timestamp : undefined };\n  });\n  const ids = new Set(bound.filter(message => message.timestamp !== undefined && message.role === \"assistant\").map(message => message.id));\n  const feedback = events.flatMap(event => event.kind === \"feedback\" && ids.has(event.messageId)\n    ? [{ sessionId, messageId: event.messageId, sourceId: event.id, topic: event.topic, signal: event.signal, timestamp: new Date(event.timestamp).toISOString() }] : []);\n  const quizResults: CliQuizWithTiming[] = [];\n  for (const event of events) {\n    if (event.kind !== \"quiz\" || !ids.has(event.messageId)) continue;\n    const record = await loadCliQuizRecord(cwd, event.quizId).catch(() => null);\n    if (!record || Date.parse(record.submission.createdAt) !== event.timestamp) continue;\n    const questions = record.submission.quiz.questions;\n    const total = questions.length;\n    if (!total) continue;\n    const exact = record.submission.objectiveResults;\n    const allExact = questions.every(question => typeof exact[question.id] === \"boolean\");\n    const reviewed = record.review?.source === \"explicit-review\" && record.review.score.total === total\n      && Number.isFinite(record.review.score.correct) && record.review.score.correct >= 0 && record.review.score.correct <= total;\n    if (!reviewed && !allExact) continue;\n    const correct = reviewed ? record.review!.score.correct : questions.filter(question => exact[question.id]).length;\n    const rawTiming = (record.submission as unknown as { timing?: { perQuestionMs?: Record<string, number> } }).timing;\n    const perQuestionMs = Object.fromEntries(Object.entries(rawTiming?.perQuestionMs ?? {}).filter(([id, value]) =>\n      questions.some(question => question.id === id) && typeof value === \"number\" && Number.isFinite(value) && value >= 0));\n    quizResults.push({ sessionId, messageId: event.messageId,\n      sourceId: `${event.id}@sha256:${cliSourceHash(JSON.stringify(reviewed ? record.review : record.submission))}`,\n      topic: record.submission.quiz.slug, timestamp: new Date(event.timestamp).toISOString(), correct, total, score: correct / total,\n      timing: { perQuestionMs } });\n  }\n  return computeCliRewardedTurns({ sessionId, messages: bound, feedback, quizResults });\n}\n\nfunction toChatMlJsonl(conversations: FineTuneConversation[]): string {\n  return conversations.map((conversation) => JSON.stringify(\n    conversation.envelope\n      ? { messages: conversation.messages, keating: conversation.envelope }\n      : { messages: conversation.messages },\n  )).join(\"\\n\") + (conversations.l