/**
 * System One (Jev) judgements, routed through Not Organic.
 *
 * Jev is hosted and needs a credential, so it cannot be called from the
 * browser. The credential belongs to **Not Organic**, not to this deployment:
 * Not Organic is the account/control plane, so it owns provider keys, per
 * customer metering, and entitlement — exactly as it already does for chat,
 * embeddings, images, audio and Tavus. Twyne holds no TypeSafe key in
 * production; it presents a DPoP-bound product assertion and calls
 * `POST /v1/judgement`, the same shape `providerIdentity.ts` uses for
 * `/v1/wallet` and `/v1/billing/checkout`.
 *
 * That boundary is what makes the tier reusable: every other property gets
 * judgements from one place, one key rotates in one place, and spend is
 * attributable per account rather than per deployment.
 *
 * `TYPESAFE_API_KEY` survives as a **local-development fallback only**, for
 * working on a judgement surface without the gateway running. It is never the
 * production path; if Not Organic is enabled the direct key is ignored.
 *
 * The question/answer shapes live in `src/utils/system-one.ts`, which is
 * transport-free and shared with the client. Deliberately no `"use node"`:
 * `fetch()` and WebCrypto both work in the default Convex runtime, and the
 * lighter runtime starts faster for what is a ~380 ms call.
 */

import { action, type ActionCtx } from "./_generated/server";
import { makeFunctionReference } from "convex/server";
import { v } from "convex/values";
import {
  directJudgementKey,
  judgementQuestions,
  validJudgementResponse,
} from "./lib/judgementContract";
import { userIsPro } from "./lib/entitlement";
import { consumeRateLimit, RATE_LIMITS } from "./lib/rateLimit";
import {
  issueNotOrganicAccessToken,
  notOrganicEnabled,
  notOrganicIssuer,
  providerJsonRequest,
} from "./lib/notorganic";

/** Direct TypeSafe endpoint. Local development only — see the module header. */
const DIRECT_ENDPOINT = "https://api.typesafe.ai/v1/systemone";
const DEFAULT_MODEL = "jev-latest";

/**
 * The provider-side route. `judgement` is a logical model the gateway resolves
 * to a concrete Jev version, the same indirection as the `fast`/`balanced`
 * aliases — so a Jev upgrade is a gateway deploy, not a release in every
 * product that asks questions.
 */
const JUDGEMENT_PATH = "/v1/judgement";
const JUDGEMENT_FEATURE = "judgement";
const JUDGEMENT_CAPABILITY = "judgement:evaluate";

const linkedDidReference = makeFunctionReference<
  "query",
  { productSubject: string },
  { did: string; sessionVersion: number } | null
>("providerIdentity:getLinkedDidBySubject");

/**
 * Questions are validated structurally rather than by kind. `v.any()` on the
 * question body would let a malformed question through to a 422; this keeps
 * the failure on our side of the wire where the message is useful.
 */
const questionValidator = v.object({
  type: v.union(v.literal("noul"), v.literal("choice"), v.literal("score")),
  instructions: v.string(),
  criteria: v.optional(v.array(v.string())),
});

/** Guards against a runaway batch costing real money or blowing the context. */
const MAX_QUESTIONS = 64;
/** 32k of the 64k context budget is for state; ~4 chars/token, conservatively. */
const MAX_STATE_CHARS = 96_000;

function directApiKey(): string | null {
  return directJudgementKey(process.env);
}

export type JudgementTransport = "notorganic" | "direct" | "none";

/**
 * Not Organic wins whenever it is enabled, even if a direct key is also
 * present. A deployment that has both is a developer machine mid-migration,
 * and silently preferring the local key there would mean shipping a surface
 * that was never exercised against the real boundary.
 */
function transport(): JudgementTransport {
  if (notOrganicEnabled()) return "notorganic";
  if (directApiKey()) return "direct";
  return "none";
}

/** Whether the deployment can answer at all, so the client can hide the tier. */
export const isAvailable = action({
  args: {},
  returns: v.object({
    available: v.boolean(),
    transport: v.union(
      v.literal("notorganic"),
      v.literal("direct"),
      v.literal("none"),
    ),
  }),
  handler: async (): Promise<{
    available: boolean;
    transport: JudgementTransport;
  }> => {
    const via = transport();
    return { available: via !== "none", transport: via };
  },
});

export interface JudgementResponse {
  model: string;
  answers: Record<string, unknown>;
  usage: { input_tokens: number; output_tokens: number };
}

/**
 * Ask Not Organic. Failures are returned, not thrown: a judgement is the
 * second rung of a ladder whose lower rungs already produced an answer, so an
 * unlinked account or a cold gateway must degrade the feature rather than
 * break the caller.
 */
async function askNotOrganic(
  ctx: ActionCtx,
  body: Record<string, unknown>,
): Promise<
  { ok: true; body: JudgementResponse } | { ok: false; error: string }
> {
  const identity = await ctx.auth.getUserIdentity();
  if (!identity) return { ok: false, error: "signed out" };

  const link = await ctx.runQuery(linkedDidReference, {
    productSubject: identity.subject || identity.tokenIdentifier,
  });
  if (!link) return { ok: false, error: "account not linked" };

  try {
    const token = await issueNotOrganicAccessToken({
      did: link.did,
      feature: JUDGEMENT_FEATURE,
      capabilities: [JUDGEMENT_CAPABILITY],
      sessionVersion: link.sessionVersion,
    });
    const result = await providerJsonRequest<JudgementResponse>(
      JUDGEMENT_PATH,
      token,
      {
        method: "POST",
        signal: AbortSignal.timeout(40_000),
        body: JSON.stringify(body),
        // The gateway reserves credit before calling upstream, so it needs a
        // key to settle against. A fresh one per attempt is deliberate: each
        // ask is a new judgement the writer asked for, and deduplicating on
        // content would silently return a stale grade for an edited draft.
        headers: { "idempotency-key": crypto.randomUUID() },
      },
      { issuer: notOrganicIssuer(), feature: JUDGEMENT_FEATURE },
    );
    return { ok: true, body: result };
  } catch (error) {
    // `providerJsonRequest` puts the upstream status in its message. Map the
    // ones a caller can act on and swallow the rest — the detail can echo the
    // request, which here is the writer's own draft.
    const message = error instanceof Error ? error.message : "";
    if (message.includes("(429)")) return { ok: false, error: "rate limited" };
    if (message.includes("(529)")) return { ok: false, error: "overloaded" };
    if (message.includes("(401)") || message.includes("(403)")) {
      return { ok: false, error: "unauthorized" };
    }
    if (message.includes("(402)")) return { ok: false, error: "no credit" };
    if (message.includes("(404)")) {
      // The gateway has not shipped `/v1/judgement` yet.
      return { ok: false, error: "unsupported" };
    }
    if (message.includes("(422)")) return { ok: false, error: "malformed" };
    return { ok: false, error: "provider" };
  }
}

/** Local-development path. Never reached when Not Organic is enabled. */
async function askDirect(
  key: string,
  body: Record<string, unknown>,
): Promise<
  { ok: true; body: JudgementResponse } | { ok: false; error: string }
> {
  let res: Response;
  try {
    res = await fetch(DIRECT_ENDPOINT, {
      method: "POST",
      signal: AbortSignal.timeout(30_000),
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${key}`,
      },
      body: JSON.stringify(body),
    });
  } catch {
    return { ok: false, error: "network" };
  }
  if (!res.ok) {
    // 429 and 529 are both "try again shortly"; the caller decides whether a
    // background pass is worth retrying at all. Never surface the body, which
    // can echo the request.
    const kind =
      res.status === 429
        ? "rate limited"
        : res.status === 529
          ? "overloaded"
          : res.status === 401
            ? "unauthorized"
            : res.status === 422
              ? "malformed"
              : `http ${res.status}`;
    return { ok: false, error: kind };
  }
  try {
    return { ok: true, body: (await res.json()) as JudgementResponse };
  } catch {
    return { ok: false, error: "provider" };
  }
}

export const ask = action({
  args: {
    state: v.record(v.string(), v.string()),
    questions: v.record(v.string(), questionValidator),
    model: v.optional(v.string()),
  },
  returns: v.object({
    ok: v.boolean(),
    model: v.optional(v.string()),
    answers: v.optional(v.record(v.string(), v.any())),
    usage: v.optional(
      v.object({ input_tokens: v.number(), output_tokens: v.number() }),
    ),
    transport: v.optional(
      v.union(v.literal("notorganic"), v.literal("direct"), v.literal("none")),
    ),
    error: v.optional(v.string()),
  }),
  handler: async (
    ctx,
    args,
  ): Promise<{
    ok: boolean;
    model?: string;
    answers?: Record<string, unknown>;
    usage?: { input_tokens: number; output_tokens: number };
    transport?: JudgementTransport;
    error?: string;
  }> => {
    const via = transport();
    // Not an error: Jev is a tier of a ladder, and every surface above it has
    // a working Tier 0/1 answer already. Degrade silently, never throw.
    if (via === "none") return { ok: false, error: "unconfigured" };

    const ids = Object.keys(args.questions);
    if (ids.length === 0) return { ok: false, error: "no questions" };
    if (ids.length > MAX_QUESTIONS) {
      return { ok: false, error: `too many questions (${ids.length})` };
    }

    const stateChars = Object.values(args.state).reduce(
      (n, s) => n + s.length,
      0,
    );
    if (stateChars > MAX_STATE_CHARS) {
      return { ok: false, error: "state too large" };
    }

    const identity = await ctx.auth.getUserIdentity();
    if (!identity) return { ok: false, error: "signed out" };
    let questions;
    try {
      questions = judgementQuestions(args.questions);
    } catch {
      return { ok: false, error: "malformed" };
    }
    if (identity) {
      const isPro = await userIsPro(ctx, identity.tokenIdentifier);
      await consumeRateLimit(ctx, {
        action: "systemOne:ask",
        identifier: identity.tokenIdentifier,
        ...(isPro ? RATE_LIMITS.systemOne : RATE_LIMITS.systemOneFree),
      });
    }

    // The gateway resolves `judgement` to a concrete Jev version, so the model
    // is only named explicitly on the direct developer path.
    const payload = {
      model: args.model ?? DEFAULT_MODEL,
      state: args.state,
      questions,
    };

    const result =
      via === "notorganic"
        ? await askNotOrganic(ctx, {
            state: args.state,
            questions,
            ...(args.model ? { model: args.model } : {}),
          })
        : await askDirect(directApiKey()!, payload);

    if (!result.ok) return { ok: false, transport: via, error: result.error };
    if (!validJudgementResponse(result.body, args.questions))
      return { ok: false, transport: via, error: "provider" };
    return {
      ok: true,
      transport: via,
      model: result.body.model,
      answers: result.body.answers,
export interface JudgementQuestion {
  type: "noul" | "choice" | "score";
  instructions: string;
  criteria?: string[];
}

/** Local development means a loopback Convex runtime, never a hosted deployment. */
export function directJudgementKey(
  env: Record<string, string | undefined>,
): string | null {
  const key = env.TYPESAFE_API_KEY?.trim();
  if (!key) return null;
  try {
    const url = new URL(env.CONVEX_CLOUD_URL || env.CONVEX_SITE_URL || "");
    return ["localhost", "127.0.0.1", "[::1]"].includes(url.hostname)
      ? key
      : null;
  } catch {
    return null;
  }
}

/** Keep the app's ordered labels, emit the current HTTP Choice map contract. */
export function judgementQuestions(
  questions: Record<string, JudgementQuestion>,
) {
  const entries = Object.entries(questions);
  if (!entries.length || entries.length > 64) throw new Error("question limit");
  const normalized = Object.fromEntries(
    entries.map(([id, q]) => {
      if (!q.instructions.trim()) throw new Error("missing instructions");
      if (q.type === "noul")
        return [id, { type: q.type, instructions: q.instructions }];
      const options = q.criteria ?? [];
      if (
        options.length < 2 ||
        options.length > 64 ||
        options.some((value) => !value.trim()) ||
        new Set(options).size !== options.length
      ) {
        throw new Error("invalid criteria");
      }
      return [
        id,
        {
          type: q.type,
          instructions: q.instructions,
          criteria:
            q.type === "choice"
              ? Object.fromEntries(options.map((value) => [value, null]))
              : options,
        },
      ];
    }),
  );
  if (JSON.stringify(normalized).length > 96_000)
    throw new Error("question limit");
  return normalized;
}

export function validJudgementResponse(
  value: unknown,
  questions: Record<string, JudgementQuestion>,
): value is {
  model: string;
  answers: Record<string, unknown>;
  usage: { input_tokens: number; output_tokens: number };
} {
  if (!value || typeof value !== "object") return false;
  const p = value as Record<string, unknown>;
  if (
    typeof p.model !== "string" ||
    !p.answers ||
    typeof p.answers !== "object" ||
    Array.isArray(p.answers)
  )
    return false;
  const usage = p.usage as Record<string, unknown> | undefined;
  if (
    !usage ||
    ![usage.input_tokens, usage.output_tokens].every(
      (n) => typeof n === "number" && Number.isSafeInteger(n) && n >= 0,
    )
  )
    return false;
  return Object.entries(questions).every(([id, q]) => {
    const a = (p.answers as Record<string, Record<string, unknown>>)[id];
    if (!a || a.type !== q.type) return false;
    if (q.type === "noul")
      return typeof a.noul === "number" && a.noul >= 0 && a.noul <= 1;
    if (
      typeof a.confidence !== "number" ||
      !Number.isFinite(a.confidence) ||
      a.confidence < 0 ||
      a.confidence > 1 ||
      !a.probabilities ||
      typeof a.probabilities !== "object" ||
      Array.isArray(a.probabilities)
    )
      return false;
    const probabilities = Object.values(a.probabilities);
    if (
      !probabilities.length ||
      !probabilities.every(
        (n) => typeof n === "number" && Number.isFinite(n) && n >= 0 && n <= 1,
      )
    )
      return false;
    if (q.type === "choice")
      return (
        typeof a.choice === "string" && Boolean(q.criteria?.includes(a.choice))
      );
    return (
      typeof a.score === "number" &&
      Number.isFinite(a.score) &&
      a.score >= 0 &&
      a.score <= (q.criteria?.length ?? 0) - 1 &&
      a.legend !== null &&
      typeof a.legend === "object" &&
      !Array.isArray(a.legend) &&
      JSON.stringify(Object.values(a.legend)) === JSON.stringify(q.criteria)
    );
  });
}
/**
 * TypeSafe "System One" (Jev) — typed questions and answers.
 *
 * Jev does not generate text. It answers a fixed set of questions about some
 * state, and returns a calibrated probability distribution for each one. That
 * is the whole surface: three question kinds, three answer shapes.
 *
 *   Noul    probability of yes, 0..1
 *   Choice  pick one option, plus the probability of every option
 *   Score   ordered levels, returning a probability-weighted value
 *
 * This module is transport-free on purpose. It builds requests and reads
 * answers; `convex/systemOne.ts` is the only place that holds the API key and
 * talks to the network, because the key must never reach the browser bundle.
 *
 * Costs, measured against the live API rather than quoted from the docs: the
 * full 11-criterion rubric spine batched into one request took 378 ms and
 * 1,401 input tokens — $0.0000588, or roughly 17,000 rubric passes per dollar.
 * Output tokens are free. This is cheap enough to run on a typing pause.
 */

/* ── Questions ─────────────────────────────────────────────────── */

/** Probability that the answer is yes. */
export interface NoulQuestion {
  type: "noul";
  instructions: string;
}

/** Pick exactly one of `criteria`. */
export interface ChoiceQuestion {
  type: "choice";
  instructions: string;
  criteria: string[];
}

/**
 * Ordered levels, worst first. The answer is a probability-weighted value
 * across them, so it can land between two levels.
 */
export interface ScoreQuestion {
  type: "score";
  instructions: string;
  criteria: string[];
}

export type SystemOneQuestion = NoulQuestion | ChoiceQuestion | ScoreQuestion;

/**
 * One request. Independent questions over the same `state` run in parallel
 * and barely change latency, so batch aggressively — but they cannot see each
 * other's answers. A second round-trip is only justified when an answer is
 * needed to *fetch* new evidence.
 *
 * Budget: 64k context per request, of which 32k is for `state`.
 */
export interface SystemOneRequest {
  model?: string;
  state: Record<string, unknown>;
  questions: Record<string, SystemOneQuestion>;
}

/* ── Answers ───────────────────────────────────────────────────── */

export interface NoulAnswer {
  type: "noul";
  /** 0 (no) to 1 (yes). */
  noul: number;
}

export interface ChoiceAnswer {
  type: "choice";
  /** The highest-probability option. */
  choice: string;
  /** Every option mapped to its probability; sums to 1. */
  probabilities: Record<string, number>;
  confidence: number;
}

export interface ScoreAnswer {
  type: "score";
  /** Probability-weighted across levels; can land between them. */
  score: number;
  /** Level index (as a string key) back to its description. */
  legend: Record<string, string>;
  /** Level index to probability; sums to 1. */
  probabilities: Record<string, number>;
  confidence: number;
}

export type SystemOneAnswer = NoulAnswer | ChoiceAnswer | ScoreAnswer;

export interface SystemOneUsage {
  input_tokens: number;
  output_tokens: number;
}

export interface SystemOneResponse {
  model: string;
  answers: Record<string, SystemOneAnswer>;
  usage: SystemOneUsage;
}

/** Input tokens only — output is not billed. */
export const USD_PER_INPUT_TOKEN = 0.042 / 1_000_000;

export function estimateCost(usage: SystemOneUsage): number {
  return usage.input_tokens * USD_PER_INPUT_TOKEN;
}

/* ── Builders ──────────────────────────────────────────────────── */

export function noul(instructions: string): NoulQuestion {
  return { type: "noul", instructions };
}

export function choice(
  instructions: string,
  criteria: string[],
): ChoiceQuestion {
  return { type: "choice", instructions, criteria };
}

/** `criteria` must be ordered worst-to-best; the index is the level. */
export function score(instructions: string, criteria: string[]): ScoreQuestion {
  return { type: "score", instructions, criteria };
}

/* ── Reading answers ───────────────────────────────────────────── */

export function isNoul(a: SystemOneAnswer | undefined): a is NoulAnswer {
  return a?.type === "noul";
}

export function isChoice(a: SystemOneAnswer | undefined): a is ChoiceAnswer {
  return a?.type === "choice";
}

export function isScore(a: SystemOneAnswer | undefined): a is ScoreAnswer {
  return a?.type === "score";
}

/**
 * Whether a Score's distribution is bimodal — mass at both ends with a trough
 * in the middle, which is exactly where the weighted mean lands.
 *
 * This is not hypothetical. A measured answer came back `score: 1.43`,
 * `confidence: 0.14`, `probabilities: {0: 0.21, 1: 0.16, 2: 0.63}`: the scalar
 * points at the level the model assigned the *least* mass to. Any threshold on
 * the scalar alone would have been wrong. Callers below their confidence floor
 * should branch on the distribution or decline to show a grade at all.
 */
export function isBimodal(answer: ScoreAnswer): boolean {
  const levels = Object.keys(answer.probabilities)
    .map(Number)
    .sort((a, b) => a - b);
  if (levels.length < 3) return false;

  const nearest = Math.round(answer.score);
  const pAtMean = answer.probabilities[String(nearest)] ?? 0;
  const peak = Math.max(...Object.values(answer.probabilities));

  // The mean sits in a trough: some level is at least twice as likely as the
  // one the mean actually names.
  return peak > pAtMean * 2;
}

/**
 * The level the model gave the most mass to, which is not always the level
 * nearest `score`. Use this when `isBimodal` is true and you still must pick.
 */
export function modalLevel(answer: ScoreAnswer): number {
  let best = 0;
  let bestP = -1;
  for (const [level, p] of Object.entries(answer.probabilities)) {
    if (p > bestP) {
      bestP = p;
      best = Number(level);
    }
  }
  return best;
}

/**
 * Rescale a Score onto 0..max (Twyne's rubric is 0–10) using the number of
 * levels the question declared, not a hardcoded assumption.
 */
export function scoreOutOf(answer: ScoreAnswer, max: number): number {
  const levels = Object.keys(answer.legend).length;
  if (levels < 2) return 0;
  return (answer.score / (levels - 1)) * max;
}

/* ── Confidence semantics ──────────────────────────────────────── */

/**
 * What `confidence` does and does not mean, kept here so call sites cannot
 * quietly reinvent it:
 *
 * - For a Noul there is no confidence field at all. A Noul near 0.5 means
 *   *equally likely yes or no* — it does not mean "medium intensity". Reading
 *   a Noul as a magnitude is the most common way to misuse this API.
 * - For Choice and Score, confidence measures how concentrated the probability
 *   distribution is. It is **not** a correctness estimate and **not**
 *   permission to act. Low confidence often just means several answers are
 *   equally fine.
 *
 * Empirically this tracks objectivity, which is the useful part: on a
 * deliberately bad draft, `integrity` scored 0.01 at confidence 0.99 while the
 * genuinely subjective `targetFit` scored 2.38 at confidence 0.43. That makes
 * confidence a good trigger for escalating to a frontier model, and a bad
 * trigger for taking an action on the user's behalf.
 */
export function confidenceOf(answer: SystemOneAnswer): number | null {
  return isNoul(answer) ? null : answer.confidence;
}
/**
 * Grading the rubric with System One (Jev).
 *
 * Twyne's rubric already had the shape TypeSafe's composite-scoring pattern
 * prescribes — a fixed spine of criteria, user-owned weights, a trend line —
 * and was missing only the cheap per-dimension scores underneath. The personas
 * could supply them, but a persona pass is a frontier call per criterion, so
 * it only ever ran on demand.
 *
 * One batched Jev request fills every criterion at once. Measured on the real
 * spine: **378 ms, 1,401 input tokens, $0.0000588** — about 17,000 full passes
 * per dollar. That is cheap enough to run on a pause in typing rather than on
 * a button, which is the entire point.
 *
 * The other half of this module matters more than the grading. Every raw
 * answer — score, confidence and the **full probability distribution** — is
 * cached. Weights, thresholds and confidence floors are then applied over that
 * cache by pure functions. Moving a slider re-renders the report with no
 * inference, no network and no cost, which is what makes a threshold something
 * a writer can learn by dragging instead of guess at once in a settings page.
 */

import type { RubricCriterionSpec } from "../types";
import {
  isScore,
  isBimodal,
  modalLevel,
  scoreOutOf,
  score as scoreQuestion,
  estimateCost,
  type ScoreQuestion,
  type SystemOneAnswer,
  type SystemOneUsage,
} from "./system-one";
import { clampWeight } from "./rubric-criteria";

/** Twyne's criteria are scored out of 10, matching `RubricCriterion.maxScore`. */
export const CRITERION_MAX = 10;

/**
 * The ladder, worst-first. Five levels rather than eleven: Jev returns a
 * probability-weighted value *between* levels, so the resolution comes from
 * the distribution, not from the number of rungs. Asking for eleven would
 * spread mass thinly and depress confidence without adding signal.
 *
 * The wording is deliberately about the reader's experience rather than about
 * a grade, because the model is being asked to predict a reaction.
 */
export const SCORE_LEVELS = [
  "Poor — a serious weakness a reader would notice immediately",
  "Weak — noticeably below standard",
  "Adequate — acceptable but unremarkable",
  "Strong — clearly well executed",
  "Excellent — a distinct strength of the piece",
];

/* ── Building the request ──────────────────────────────────────── */

/**
 * One Score question per enabled criterion. `engagement` is excluded for the
 * same reason `weightedCriteriaScore` excludes it: it is derived from the
 * combined grade, so scoring it here would make the grade partly a function of
 * itself.
 */
export function buildRubricQuestions(
  specs: RubricCriterionSpec[],
): Record<string, ScoreQuestion> {
  const questions: Record<string, ScoreQuestion> = {};
  for (const spec of specs) {
    if (!spec.enabled || spec.id === "engagement") continue;
    questions[spec.id] = scoreQuestion(
      `Rate the draft on ${spec.label}: ${spec.description}.`,
      SCORE_LEVELS,
    );
  }
  return questions;
}

/**
 * The evidence Jev reads. Separate keys rather than one concatenated blob so
 * the model can tell the draft apart from the brief describing it — a draft
 * that fails its own stated goal is the single most useful thing `targetFit`
 * can detect, and it cannot detect it if the goal is buried in the prose.
 */
export function buildRubricState(input: {
  draft: string;
  audience?: string;
  goal?: string;
}): Record<string, string> {
  const state: Record<string, string> = { draft: input.draft };
  if (input.audience) state.audience = input.audience;
  if (input.goal) state.goal = input.goal;
  return state;
}

/* ── Reading the answers ───────────────────────────────────────── */

/** One criterion's cached answer, kept whole so thresholds can move later. */
export interface GradedCriterion {
  id: string;
  /** Rescaled to 0–10 to match the rest of the rubric. */
  score: number;
  /** The raw probability-weighted level, 0..levels-1. */
  level: number;
  /** Distribution concentration, 0..1. Not a correctness estimate. */
  confidence: number;
  /** Level index to probability. The part a scalar throws away. */
  probabilities: Record<string, number>;
  legend: Record<string, string>;
  /** The mean sits in a trough — see `isBimodal`. */
  bimodal: boolean;
  /** Highest-mass level, which is not always the one nearest `score`. */
  modal: number;
}

/** A whole cached pass. Everything a report needs, with nothing applied yet. */
export interface RubricGrade {
  at: number;
  model: string;
  criteria: Record<string, GradedCriterion>;
  usage: SystemOneUsage;
  costUsd: number;
}

export function readRubricAnswers(
  answers: Record<string, SystemOneAnswer>,
  meta: { model: string; usage: SystemOneUsage },
): RubricGrade {
  const criteria: Record<string, GradedCriterion> = {};
  for (const [id, answer] of Object.entries(answers)) {
    // A non-Score answer here means the request and the reader disagree about
    // the question kind. Skip rather than coerce: a wrong number displayed
    // confidently is worse than a missing criterion.
    if (!isScore(answer)) continue;
    criteria[id] = {
      id,
      score: scoreOutOf(answer, CRITERION_MAX),
      level: answer.score,
      confidence: answer.confidence,
      probabilities: answer.probabilities,
      legend: answer.legend,
      bimodal: isBimodal(answer),
      modal: modalLevel(answer),
    };
  }
  return {
    at: Date.now(),
    model: meta.model,
    criteria,
    usage: meta.usage,
    costUsd: estimateCost(meta.usage),
  };
}

/* ── Applying thresholds, over the cache only ──────────────────── */

/**
 * The advanced knobs, which live in the deep report beside the evidence rather
 * than in the settings page. Every one of them is applied by the pure
 * functions below, over an already-fetched `RubricGrade`.
 */
export interface RubricThresholds {
  /**
   * Hide a criterion whose confidence is below this. Default 0 — show
   * everything and mark it — because hiding by default teaches the writer
   * nothing about why a criterion vanished.
   */
  confidenceFloor: number;
  /**
   * Below this confidence, offer to spend a frontier persona pass on the
   * criterion. Confidence tracks objectivity, so this naturally escalates the
   * subjective criteria and leaves the mechanical ones alone.
   */
  escalateBelow: number;
  /** A score at or under this is called out as a weakness. */
  weakAtOrBelow: number;
  /** A score at or above this is called out as a strength. */
  strongAtOrAbove: number;
}

export const DEFAULT_THRESHOLDS: RubricThresholds = {
  confidenceFloor: 0,
  escalateBelow: 0.5,
  weakAtOrBelow: 4,
  strongAtOrAbove: 8,
};

export type CriterionVerdict = "weak" | "strong" | "middling";

export interface CriterionView extends GradedCriterion {
  verdict: CriterionVerdict;
  /** Below the floor: shown greyed with a reason, not silently dropped. */
  belowFloor: boolean;
  /** Worth a frontier second opinion. */
  escalate: boolean;
  /** Don't trust the scalar; the distribution disagrees with it. */
  unreliableScalar: boolean;
  weight: number;
}

/**
 * Project a cached pass through the current specs and thresholds.
 *
 * Pure and synchronous by design: this is the function a slider's `onInput`
 * calls. If it ever needs to await anything, the caching design has been
 * broken and a drag will start firing network requests.
 */
export function viewRubricGrade(
  grade: RubricGrade,
  specs: RubricCriterionSpec[],
  thresholds: RubricThresholds = DEFAULT_THRESHOLDS,
): CriterionView[] {
  const views: CriterionView[] = [];
  for (const spec of specs) {
    if (!spec.enabled) continue;
    const graded = grade.criteria[spec.id];
    if (!graded) continue;
    views.push({
      ...graded,
      weight: clampWeight(spec.weight),
      belowFloor: graded.confidence < thresholds.confidenceFloor,
      escalate: graded.confidence < thresholds.escalateBelow,
      // A bimodal distribution means the weighted mean landed where the model
      // put the least mass, so the *score* is not describing the answer even
      // though it is perfectly well-formed.
      unreliableScalar: graded.bimodal,
      verdict:
        graded.score <= thresholds.weakAtOrBelow
          ? "weak"
          : graded.score >= thresholds.strongAtOrAbove
            ? "strong"
            : "middling",
    });
  }
  return views;
}

/**
 * Plain `{id: score}`, ready for the existing `weightedCriteriaScore`. Kept
 * separate so the writer's weights keep their single implementation instead of
 * gaining a second one here.
 */
export function gradeScores(grade: RubricGrade): Record<string, number> {
  return Object.fromEntries(
    Object.values(grade.criteria).map((c) => [c.id, c.score]),
  );
}

/**
 * How far the thresholds have drifted from the shipped defaults, so the report
 * can say so. A writer who has tuned four knobs and forgotten is otherwise
 * looking at a report they can no longer interpret.
 */
export function driftedKeys(t: RubricThresholds): (keyof RubricThresholds)[] {
  return (Object.keys(DEFAULT_THRESHOLDS) as (keyof RubricThresholds)[]).filter(
    (k) => t[k] !== DEFAULT_THRESHOLDS[k],
  );
}

/* ── Running a pass ────────────────────────────────────────────── */

/**
 * The transport, narrowed to what this module needs. Declared structurally
 * rather than importing the Convex client so the grading logic stays testable
 * without a backend, and so the caller decides which client instance to use.
 */
export interface JudgementCaller {
  (input: {
    state: Record<string, string>;
    questions: Record<string, ScoreQuestion>;
  }): Promise<{
    ok: boolean;
    model?: string;
    answers?: Record<string, unknown>;
    usage?: SystemOneUsage;
    error?: string;
  }>;
}

export type RubricPass =
  | { ok: true; grade: RubricGrade }
  | { ok: false; error: string };

/**
 * One batched pass over the writer's enabled criteria.
 *
 * Measured on the real spine: **378 ms, 1,401 input tokens, $0.0000588**. The
 * whole rubric is a single request because Jev evaluates every question
 * against the same state in parallel, so an eleventh criterion costs the
 * tokens of its own wording and nothing else.
 *
 * Returns a result rather than throwing. This is the second rung of a ladder
 * whose lower rung — the deterministic static score — has already produced a
 * number, so a failure here degrades the report instead of emptying it.
 */
export async function runRubricPass(
  ask: JudgementCaller,
  input: { draft: string; audience?: string; goal?: string },
  specs: RubricCriterionSpec[],
): Promise<RubricPass> {
  const questions = buildRubricQuestions(specs);
  if (Object.keys(questions).length === 0) {
    return { ok: false, error: "no criteria enabled" };
  }
  if (!input.draft.trim()) return { ok: false, error: "empty draft" };

  let response: Awaited<ReturnType<JudgementCaller>>;
  try {
    response = await ask({ state: buildRubricState(input), questions });
  } catch {
    return { ok: false, error: "unreachable" };
  }

  if (!response.ok || !response.answers) {
    return { ok: false, error: response.error ?? "no answers" };
  }
  return {
    ok: true,
    grade: readRubricAnswers(
      response.answers as Record<string, SystemOneAnswer>,
      {
        model: response.model ?? "unknown",
        usage: response.usage ?? { input_tokens: 0, output_tokens: 0 },
      },
    ),
  };
}

