  1	/** Export the existing default web tutor prompt without opening learner storage. */
  2	import { plugin } from "bun";
  3	import { createHash } from "node:crypto";
  4	import { chmod, mkdir, readFile, readdir, writeFile } from "node:fs/promises";
  5	import { dirname, resolve } from "node:path";
  6	import { createRequire } from "node:module";
  7	import ts from "typescript";
  8	
  9	const root = resolve(import.meta.dir, "../..");
 10	const output = resolve(root, process.argv[2] ?? ".keating/outputs/training/system-prompt.txt");
 11	const digest = (value: string | Buffer) => createHash("sha256").update(value).digest("hex");
 12	
 13	// Bun does not implement Vite's ?raw import convention. Read the same checked-in
 14	// bytes that Vite supplies; all prose continues to come from application modules.
 15	await plugin({
 16	  name: "keating-prompt-raw-markdown",
 17	  setup(build) {
 18	    build.onLoad({ filter: /\.md(?:\?raw)?$/ }, async (args) => ({
 19	      contents: `export default ${JSON.stringify(await Bun.file(args.path.replace(/\?raw$/, "")).text())};`,
 20	      loader: "js",
 21	    }));
 22	  },
 23	});
 24	
 25	const { buildKeatingSystemPrompt, composeKeatingSystemPrompt } = await import(
 26	  "../../web/src/keating/browser-tools/prompt"
 27	);
 28	const { DEFAULT_TEACHER_PERSONA } = await import("../../web/src/keating/persona");
 29	const { defaultDeclaredProfile } = await import("../../packages/learner-contracts/src/learner-profile-declared.js");
 30	const { keatingOpenUIPrompt } = await import("../../web/src/keating/openui/library");
 31	const { composeSessionStartSystemPrompt } = await import("../../web/src/keating/session-start-hooks");
 32	const { appendWorkspaceCapabilityPrompt } = await import("../../web/src/keating/capabilities");
 33	const { appendCourseCollaborationPrompt } = await import("../../web/src/keating/browser-tools/courses");
 34	// A transitive PDF dependency allocates a DOMMatrix at import time. Use the
 35	// installed real canvas implementation for Node compatibility; no tool code or
 36	// schemas are replaced, and no PDF/media processing runs during this export.
 37	if (typeof globalThis.DOMMatrix === "undefined") {
 38	  const webRequire = createRequire(resolve(root, "web/package.json"));
 39	  globalThis.DOMMatrix = webRequire("@napi-rs/canvas").DOMMatrix;
 40	}
 41	const { createKeatingTools } = await import("../../web/src/keating/browser-tools");
 42	const { filterAvailableKeatingTools } = await import("../../web/src/keating/capabilities");
 43	const { KeatingStorage } = await import("../../web/src/keating/storage");
 44	
 45	// The real storage constructor only records its database name. Never initialize
 46	// it or invoke tools: this exports the application's declarations, not results.
 47	const declarationStorage = new KeatingStorage("keating-training-schema-export-unused");
 48	const registeredTools = await createKeatingTools(declarationStorage, {});
 49	const availableTools = filterAvailableKeatingTools(registeredTools, {
 50	  runtime: undefined, speechEnabled: false, clientWebSearch: false,
 51	});
