 62	const base = composeKeatingSystemPrompt(DEFAULT_TEACHER_PERSONA);
 63	// Supply the real empty profile explicitly: the hook's default loader reads
 64	// browser storage, which must remain outside a new-user prompt export.
 65	const declaredProfile = defaultDeclaredProfile();
 66	const withLearner = buildKeatingSystemPrompt(false, base, "", declaredProfile);
 67	const withOpenUi = base.includes(keatingOpenUIPrompt)
 68	  ? withLearner
 69	  : `${withLearner}\n\n${keatingOpenUIPrompt}`;
 70	const composed = appendCourseCollaborationPrompt(
 71	  appendWorkspaceCapabilityPrompt(composeSessionStartSystemPrompt(withOpenUi, ""), { runtime: undefined }),
 72	  undefined,
 73	);
 74	
 75	// Independently execute the actual builder declaration from the React hook. We
 76	// deliberately avoid importing that hook, which initializes application storage.
 77	// TypeScript removes only types; dependencies are the same functions imported above.
 78	const hookPath = "web/src/hooks/useKeatingAgent.tsx";
 79	const hook = await readFile(resolve(root, hookPath), "utf8");
 80	const sourceFile = ts.createSourceFile(hookPath, hook, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX);
 81	const builders = sourceFile.statements.filter((node): node is ts.FunctionDeclaration =>
 82	  ts.isFunctionDeclaration(node) && node.name?.text === "buildAgentSystemPrompt",
 83	);
 84	if (builders.length !== 1) throw new Error("Expected exactly one original web prompt builder");
 85	const originalSource = builders[0]!.getText(sourceFile);
 86	const executable = ts.transpileModule(originalSource, {
 87	  compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.None },
 88	  reportDiagnostics: true,
 89	});
 90	if (executable.diagnostics?.some((diagnostic) => diagnostic.category === ts.DiagnosticCategory.Error)) {
 91	  throw new Error("Could not compile original web prompt builder");
 92	}
 93	const originalBuilder = new Function(
 94	  "buildKeatingSystemPrompt", "keatingOpenUIPrompt", "composeSessionStartSystemPrompt",
 95	  "appendWorkspaceCapabilityPrompt", "appendCourseCollaborationPrompt",
 96	  `${executable.outputText}\nreturn buildAgentSystemPrompt;`,
 97	)(buildKeatingSystemPrompt, keatingOpenUIPrompt, composeSessionStartSystemPrompt,
 98	  appendWorkspaceCapabilityPrompt, appendCourseCollaborationPrompt);
 99	const original = originalBuilder(false, base, "", "", undefined, undefined, declaredProfile);
100	if (typeof original !== "string" || original !== composed) {
101	  throw new Error("Export differs from the original web hook prompt builder");
102	}
103	if (original.split(keatingOpenUIPrompt).length !== 2) {
104	  throw new Error("OpenUI prompt must appear exactly once");
105	}
106	
107	const inputs = [
108	  "scripts/training/export_system_prompt.ts",
109	  hookPath, "web/src/keating/browser-tools/prompt.ts", "web/src/keating/persona.ts",
110	  "web/src/keating/learner-context.ts", "packages/learner-contracts/src/learner-profile-declared.ts", "web/src/keating/prompts/operational-protocol.md",
111	  "web/src/keating/prompts/speech-system-prompt.md", "web/src/keating/openui/library.tsx",
112	  "web/src/keating/session-start-hooks.ts", "web/src/keating/capabilities.ts",
113	  "web/src/keating/browser-tools/courses.ts", "web/package.json", "bun.lock",
114	  "web/src/keating/browser-tools.ts", "web/src/keating/storage.ts", "web/src/keating/speech.ts",
115	  ...(await readdir(resolve(root, "web/src/keating/browser-tools")))
116	    .filter((name) => name.endsWith(".ts"))
