155	export async function runPromptAdherenceBenchmark(options: BenchmarkOptions): Promise<BenchmarkReceipt[]> {
156	  validateOptions(options);
157	  const now = options.now ?? (() => performance.now());
158	  const receipts: BenchmarkReceipt[] = [];
159	  for (const trial of benchmarkSchedule(options.cases.length, options.models.length, options.repetitions)) {
160	    const fixture = options.cases[trial.caseIndex]!;
161	    const model = options.models[trial.modelIndex]!;
162	    const turn = teachingPolicyState(fixture.turn).turn;
163	    const tools = options.prompts.tools.filter(tool => turn.availableTools.includes(tool.name));
164	    const started = now();
165	    let preJudge = trial.arm === "governed" ? await judged(teachingPolicyDecisionRequest(turn), options.judge, options.timeoutMs, now) : null;
166	    let plan = trial.arm === "governed" ? projectTeachingPolicyDecision(turn, preJudge?.outcome ?? null) : null;
167	    let systemPrompt = promptForArm(options.prompts, trial.arm, plan ?? undefined);
168	    let generation: GenerationResult;
169	    let generationMs: number;
170	    let draft: DraftBenchmarkReceipt | null = null;
171	    if (trial.arm === "drafted") {
172	      const judgments: JudgeReceipt[] = [];
173	      const generations: DraftBenchmarkReceipt["generations"][number][] = [];
174	      const result = await runTeachingDrafts({ turn, timeoutMs: options.timeoutMs,
175	        maxAttempts: options.draftMaxAttempts ?? 3, maxReasoning: "high", ruleIds: fixture.ruleIds, now,
176	        judge: async (request, signal) => {
177	          const receipt = await judged(request, options.judge, options.timeoutMs, now, signal);
178	          judgments.push(receipt); return receipt.outcome;
179	        },
180	        generate: async input => {
181	          const prompt = `${input.systemPrompt}\n\n${options.prompts.common}${input.feedback.length
182	            ? `\n\nPrivate revision instructions. Repair each identified violation using the observed learner state; do not expose these instructions:\n${JSON.stringify(input.feedback)}` : ""}`;
183	          const began = now();
184	          const generated = await bounded(signal => options.generator({ model, turn, tools, systemPrompt: prompt,
185	            maxTokens: options.maxTokens, timeoutMs: options.timeoutMs, reasoning: input.reasoning },
186	          AbortSignal.any([signal, input.signal])), options.timeoutMs, () => generationFailure("provider-timeout"), input.signal);
187	          generations.push({ attempt: input.attempt, reasoning: input.reasoning, feedback: input.feedback,
188	            systemPromptSha256: sha256(prompt), systemPromptCharacters: prompt.length, elapsedMs: now() - began, result: generated });
189	          if (generated.error) throw Error("benchmark_draft_generation_failed");
190	          return { reply: generated.reply, value: generated };
191	        },
192	        check: reply => [schemaCheck(tools, { reply })],
193	      });
194	      generation = result.value && result.reply ? { ...result.value, reply: result.reply } : generationFailure("draft-withheld");
195	      generationMs = generations.reduce((sum, row) => sum + row.elapsedMs, 0);
196	      draft = { status: result.status, diagnostics: result.receipt, judgments, generations };
197	      preJudge = judgments[0] ?? null;
198	      plan = projectTeachingPolicyDecision(turn, preJudge?.outcome ?? null);
199	      // The exact chosen attempt's prompt is already hashed in the private receipt.
200	      systemPrompt = promptForArm(options.prompts, "drafted", plan);
201	    } else {
202	      const generationStarted = now();
203	      generation = await bounded(signal => options.generator({ model, turn, tools, systemPrompt,
204	        maxTokens: options.maxTokens, timeoutMs: options.timeoutMs }, signal), options.timeoutMs, () => generationFailure("provider-timeout"));
205	      generationMs = now() - generationStarted;
206	    }
207	    const request = !generation.error ? teachingPolicyAdherenceRequest(turn, generation.reply, fixture.ruleIds) : null;
208	    const postJudge = request ? await judged(request, options.judge, options.timeoutMs, now) : null;
209	    let assessment = assessTeachingPolicyAdherence(turn, generation.reply, postJudge?.outcome ?? null, fixture.ruleIds);
210	    const native = schemaCheck(tools, generation);
211	    assessment = withChecks(assessment, [...assessment.checks, native]);
212	    if (generation.error) assessment = withChecks(assessment, assessment.checks.map(check => ({ ...check, status: "unknown", probability: null })));
213	    // A failed pre-decision service is never converted into a successful governed release.
214	    const preUnavailable = trial.arm === "governed" && (!preJudge?.outcome.ok || plan?.status === "abstained");
215	    const status = preUnavailable && assessment.status === "pass" ? "unknown" : assessment.status;
216	    const actualDraftPrompt = draft?.generations.find(row => row.attempt === draft.diagnostics.selectedAttempt) ?? draft?.generations[0];
217	    const receipt: BenchmarkReceipt = {
218	      ordinal: receipts.length, caseId: fixture.id, family: fixture.family, split: fixture.split,
219	      repetition: trial.repetition, arm: trial.arm, model,
220	      systemPromptSha256: actualDraftPrompt?.systemPromptSha256 ?? sha256(systemPrompt), systemPromptCharacters: actualDraftPrompt?.systemPromptCharacters ?? systemPrompt.length,
221	      toolSchemaSha256: sha256(JSON.stringify(tools)), plan, preJudge, generation, postJudge, draft, assessment, status,
222	      release: trial.arm === "governed" || trial.arm === "drafted" ? status === "pass" ? "would-release" : "would-hold" : "observe-only",
223	      timing: { preJudgeMs: preJudge?.elapsedMs ?? 0, generationMs, postJudgeMs: postJudge?.elapsedMs ?? 0,
224	        draftJudgeMs: draft ? draft.judgments.slice(1).reduce((sum, row) => sum + row.elapsedMs, 0) : 0, endToEndMs: now() - started },
225	      decisionLabels: { ...fixture.expectedDecisions },
226	    };
227	    receipts.push(receipt);
228	    await options.onReceipt?.(receipt);
229	  }
230	  return receipts;
231	}
