 96	function selected(outcome: JudgementOutcome, id: string, question: ChoiceQuestion): string | null {
 97	  if (!outcome.ok) return null;
 98	  const answer = decodeAnswer(question, outcome.response.answers[id]);
 99	  return answer?.type === "choice" && answer.choice !== "no_match" ? answer.choice : null;
100	}
