 51	  readonly generations: readonly { readonly attempt: number; readonly reasoning: TeachingDraftReasoning;
 52	    readonly feedback: readonly TeachingDraftFeedback[]; readonly systemPromptSha256: string;
 53	    readonly systemPromptCharacters: number; readonly elapsedMs: number; readonly result: GenerationResult }[];
 54	}
 55	export interface JudgeFixtureReceipt {
 56	  readonly id: string;
 57	  readonly family: string;
 58	  readonly split: "development" | "holdout";
 59	  readonly labels: Readonly<Record<string, boolean>>;
 60	  readonly judge: JudgeReceipt | null;
 61	  readonly assessment: TeachingPolicyAssessment;
 62	}
 63	export interface BenchmarkOptions {
 64	  readonly models: readonly BenchmarkModel[];
 65	  readonly cases: readonly TeachingPolicyCase[];
 66	  readonly prompts: PromptArtifacts;
 67	  readonly repetitions: number;
 68	  readonly maxTokens: number;
 69	  readonly timeoutMs: number;
 70	  readonly generator: BenchmarkGenerator;
 71	  readonly judge: JudgementCaller;
 72	  readonly draftMaxAttempts?: number;
 73	  readonly now?: () => number;
 74	  readonly onReceipt?: (receipt: BenchmarkReceipt) => Promise<void>;
 75	}
 76	export interface ScheduledTrial { readonly caseIndex: number; readonly modelIndex: number; readonly arm: BenchmarkArm; readonly repetition: number }
 77	
 78	/** Balanced rotations reduce arm/model position bias without selecting on outcomes. */
 79	export function benchmarkSchedule(caseCount: number, modelCount: number, repetitions: number): ScheduledTrial[] {
 80	  const schedule: ScheduledTrial[] = [];
 81	  for (let repetition = 0; repetition < repetitions; repetition++) {
 82	    for (let caseIndex = 0; caseIndex < caseCount; caseIndex++) {
 83	      const offset = caseIndex + repetition;
 84	      const arms = BENCHMARK_ARMS.map((_, index) => BENCHMARK_ARMS[(index + offset) % BENCHMARK_ARMS.length]!);
 85	      for (let slot = 0; slot < modelCount; slot++) {
 86	        const modelIndex = (slot + offset) % modelCount;
 87	        for (const arm of repetition % 2 === 0 ? arms : [...arms].reverse()) schedule.push({ caseIndex, modelIndex, arm, repetition });
 88	      }
 89	    }
 90	  }
 91	  return schedule;
 92	}
 93	
 94	async function bounded<T>(call: (signal: AbortSignal) => Promise<T>, timeoutMs: number, failure: () => T, externalSignal?: AbortSignal): Promise<T> {
 95	  const controller = new AbortController();
 96	  let timer: ReturnType<typeof setTimeout> | undefined;
 97	  let onAbort: (() => void) | undefined;
 98	  try {
 99	    if (externalSignal?.aborted) return failure();
100	    return await Promise.race([
101	      call(controller.signal).catch(failure),
102	      new Promise<T>(resolve => { timer = setTimeout(() => { controller.abort(); resolve(failure()); }, timeoutMs); }),
103	      new Promise<T>(resolve => {
104	        onAbort = () => { controller.abort(); resolve(failure()); };
105	        externalSignal?.addEventListener("abort", onAbort, { once: true });
106	      }),
107	    ]);
108	  } catch { return failure(); }
109	  finally { if (timer) clearTimeout(timer); if (onAbort) externalSignal?.removeEventListener("abort", onAbort); }
110	}
111	
112	async function judged(request: JudgementRequest, judge: JudgementCaller, timeoutMs: number, now: () => number, externalSignal?: AbortSignal): Promise<JudgeReceipt> {
113	  const started = now();
114	  const outcome = await bounded(signal => judge(request, signal), timeoutMs,
115	    (): JudgementOutcome => ({ ok: false, error: { code: "backend-timeout", retryable: false } }), externalSignal);
116	  return { request, requestSha256: sha256(JSON.stringify(request)), outcome, elapsedMs: now() - started, attempts: 1, cache: "none" };
117	}
118	
119	function schemaCheck(tools: readonly BenchmarkTool[], generation: Pick<GenerationResult, "reply">): TeachingPolicyCheck {
120	  let valid = true;
121	  for (const call of generation.reply.toolCalls) {
122	    try {
123	      const original = JSON.stringify(call.arguments);
124	      const declared = tools.map(tool => ({ ...tool, parameters: tool.parameters as Parameters<typeof validateToolCall>[0][number]["parameters"] }));
125	      const checked: unknown = validateToolCall(declared, {
126	        type: "toolCall", id: "benchmark-proposal", name: call.name,
127	        arguments: structuredClone(call.arguments) as Record<string, unknown>,
128	      });
129	      // Coercion is not evidence the emitted arguments met the schema.
130	      if (JSON.stringify(checked) !== original) valid = false;
131	    } catch { valid = false; }
132	  }
133	  return { id: "native_tool_schema", source: "deterministic", severity: "critical", status: valid ? "pass" : "fail", probability: valid ? 0 : 1 };
134	}
135	
136	function withChecks(assessment: TeachingPolicyAssessment, checks: readonly TeachingPolicyCheck[]): TeachingPolicyAssessment {
137	  const failed = checks.filter(check => check.status === "fail").map(check => check.id);
138	  const uncertain = checks.filter(check => check.status === "unknown").map(check => check.id);
139	  return { ...assessment, checks, failed, uncertain, status: failed.length ? "fail" : uncertain.length ? "unknown" : "pass" };
140	}
141	
142	function validateOptions(options: BenchmarkOptions): void {
143	  if (!options.models.length || options.models.length > 20 || options.models.some(model => !isAllowedBenchmarkModel(model))) throw Error("benchmark_models_invalid");
144	  if (new Set(options.models.map(model => model.id)).size !== options.models.length) throw Error("benchmark_duplicate_models");
145	  if (!options.cases.length || options.cases.length > 1000 || new Set(options.cases.map(row => row.id)).size !== options.cases.length) throw Error("benchmark_cases_invalid");
146	  if (!Number.isInteger(options.repetitions) || options.repetitions < 1 || options.repetitions > 20) throw Error("benchmark_repetitions_invalid");
147	  if (!Number.isInteger(options.maxTokens) || options.maxTokens < 64 || options.maxTokens > 8192) throw Error("benchmark_token_limit_invalid");
148	  if (!Number.isInteger(options.timeoutMs) || options.timeoutMs < 1 || options.timeoutMs > 300_000) throw Error("benchmark_timeout_invalid");
149	  if (options.draftMaxAttempts !== undefined && (!Number.isInteger(options.draftMaxAttempts) || options.draftMaxAttempts < 1 || options.draftMaxAttempts > 5)) throw Error("benchmark_draft_attempts_invalid");
150	  for (const row of options.cases) {
151	    if (row.turn.availableTools.some(name => !options.prompts.tools.some(tool => tool.name === name))) throw Error(`benchmark_fixture_tool_not_in_web_export:${row.id}`);
152	  }
153	}
154	
155	export async function runPromptAdherenceBenchmark(options: BenchmarkOptions): Promise<BenchmarkReceipt[]> {
156	  validateOptions(options);
157	  const now = options.now ?? (() => performance.now());
158	  const receipts: BenchmarkReceipt[] = [];
159	  for (const trial of benchmarkSchedule(options.cases.length, options.models.length, options.repetitions)) {
160	    const fixture = options.cases[trial.caseIndex]!;
161	    const model = options.models[trial.modelIndex]!;
162	    const turn = teachingPolicyState(fixture.turn).turn;
163	    const tools = options.prompts.tools.filter(tool => turn.availableTools.includes(tool.name));
164	    const started = now();
165	    let preJudge = trial.arm === "governed" ? await judged(teachingPolicyDecisionRequest(turn), options.judge, options.timeoutMs, now) : null;
166	    let plan = trial.arm === "governed" ? projectTeachingPolicyDecision(turn, preJudge?.outcome ?? null) : null;
167	    let systemPrompt = promptForArm(options.prompts, trial.arm, plan ?? undefined);
168	    let generation: GenerationResult;
169	    let generationMs: number;
170	    let draft: DraftBenchmarkReceipt | null = null;
171	    if (trial.arm === "drafted") {
172	      const judgments: JudgeReceipt[] = [];
173	      const generations: DraftBenchmarkReceipt["generations"][number][] = [];
174	      const result = await runTeachingDrafts({ turn, timeoutMs: options.timeoutMs,
175	        maxAttempts: options.draftMaxAttempts ?? 3, maxReasoning: "high", ruleIds: fixture.ruleIds, now,
176	        judge: async (request, signal) => {
177	          const receipt = await judged(request, options.judge, options.timeoutMs, now, signal);
178	          judgments.push(receipt); return receipt.outcome;
179	        },
180	        generate: async input => {
181	          const prompt = `${input.systemPrompt}\n\n${options.prompts.common}${input.feedback.length
182	            ? `\n\nPrivate revision instructions. Repair each identified violation using the observed learner state; do not expose these instructions:\n${JSON.stringify(input.feedback)}` : ""}`;
183	          const began = now();
184	          const generated = await bounded(signal => options.generator({ model, turn, tools, systemPrompt: prompt,
185	            maxTokens: options.maxTokens, timeoutMs: options.timeoutMs, reasoning: input.reasoning },
186	          AbortSignal.any([signal, input.signal])), options.timeoutMs, () => generationFailure("provider-timeout"), input.signal);
187	          generations.push({ attempt: input.attempt, reasoning: input.reasoning, feedback: input.feedback,
188	            systemPromptSha256: sha256(prompt), systemPromptCharacters: prompt.length, elapsedMs: now() - began, result: generated });
189	          if (generated.error) throw Error("benchmark_draft_generation_failed");
190	          return { reply: generated.reply, value: generated };
191	        },
192	        check: reply => [schemaCheck(tools, { reply })],
193	      });
194	      generation = result.value && result.reply ? { ...result.value, reply: result.reply } : generationFailure("draft-withheld");
195	      generationMs = generations.reduce((sum, row) => sum + row.elapsedMs, 0);
196	      draft = { status: result.status, diagnostics: result.receipt, judgments, generations };
197	      preJudge = judgments[0] ?? null;
198	      plan = projectTeachingPolicyDecision(turn, preJudge?.outcome ?? null);
199	      // The exact chosen attempt's prompt is already hashed in the private receipt.
200	      systemPrompt = promptForArm(options.prompts, "drafted", plan);
201	    } else {
202	      const generationStarted = now();
203	      generation = await bounded(signal => options.generator({ model, turn, tools, systemPrompt,
204	        maxTokens: options.maxTokens, timeoutMs: options.timeoutMs }, signal), options.timeoutMs, () => generationFailure("provider-timeout"));
205	      generationMs = now() - generationStarted;
206	    }
207	    const request = !generation.error ? teachingPolicyAdherenceRequest(turn, generation.reply, fixture.ruleIds) : null;
208	    const postJudge = request ? await judged(request, options.judge, options.timeoutMs, now) : null;
209	    let assessment = assessTeachingPolicyAdherence(turn, generation.reply, postJudge?.outcome ?? null, fixture.ruleIds);
210	    const native = schemaCheck(tools, generation);
211	    assessment = withChecks(assessment, [...assessment.checks, native]);
212	    if (generation.error) assessment = withChecks(assessment, assessment.checks.map(check => ({ ...check, status: "unknown", probability: null })));
213	    // A failed pre-decision service is never converted into a successful governed release.
214	    const preUnavailable = trial.arm === "governed" && (!preJudge?.outcome.ok || plan?.status === "abstained");
215	    const status = preUnavailable && assessment.status === "pass" ? "unknown" : assessment.status;
216	    const actualDraftPrompt = draft?.generations.find(row => row.attempt === draft.diagnostics.selectedAttempt) ?? draft?.generations[0];
217	    const receipt: BenchmarkReceipt = {
218	      ordinal: receipts.length, caseId: fixture.id, family: fixture.family, split: fixture.split,
219	      repetition: trial.repetition, arm: trial.arm, model,
220	      systemPromptSha256: actualDraftPrompt?.systemPromptSha256 ?? sha256(systemPrompt), systemPromptCharacters: actualDraftPrompt?.systemPromptCharacters ?? systemPrompt.length,
221	      toolSchemaSha256: sha256(JSON.stringify(tools)), plan, preJudge, generation, postJudge, draft, assessment, status,
222	      release: trial.arm === "governed" || trial.arm === "drafted" ? status === "pass" ? "would-release" : "would-hold" : "observe-only",
223	      timing: { preJudgeMs: preJudge?.elapsedMs ?? 0, generationMs, postJudgeMs: postJudge?.elapsedMs ?? 0,
224	        draftJudgeMs: draft ? draft.judgments.slice(1).reduce((sum, row) => sum + row.elapsedMs, 0) : 0, endToEndMs: now() - started },
225	      decisionLabels: { ...fixture.expectedDecisions },
226	    };
227	    receipts.push(receipt);
228	    await options.onReceipt?.(receipt);
229	  }
230	  return receipts;
231	}
232	
233	/** Evaluation only: no threshold fitting, candidate search, or updates from holdout labels. */
234	export async function validateJudgeFixtures(fixtures: readonly TeachingPolicyJudgeFixture[], judge: JudgementCaller,
235	  timeoutMs: number, onReceipt?: (receipt: JudgeFixtureReceipt) => Promise<void>): Promise<JudgeFixtureReceipt[]> {
236	  const receipts: JudgeFixtureReceipt[] = [];
237	  for (const fixture of fixtures) {
238	    const ruleIds = Object.keys(fixture.violations);
239	    const request = teachingPolicyAdherenceRequest(fixture.turn, fixture.reply, ruleIds);
240	    const receipt = request ? await judged(request, judge, timeoutMs, () => performance.now()) : null;
241	    const result: JudgeFixtureReceipt = { id: fixture.id, family: fixture.family, split: fixture.split,
242	      labels: fixture.violations, judge: receipt,
243	      assessment: assessTeachingPolicyAdherence(fixture.turn, fixture.reply, receipt?.outcome ?? null, ruleIds) };
244	    receipts.push(result);
245	    await onReceipt?.(result);
246	  }
247	  return receipts;
248	}

