import type { Persona, ProjectBrief, WriterProfile } from "../types";
import {
  buildNoteQuestions,
  buildNoteState,
  readNoteVerdict,
  type NoteVerdict,
} from "./note-gate";
import type { SystemOneAnswer } from "./system-one";
import type { WritingLensCaller } from "./writing-lenses";

/** Missing answers are unavailable, never a synthetic pass or a veto. */
export async function reviewEditorialNote(
  call: WritingLensCaller,
  input: {
    note: string;
    quote?: string;
    draft: string;
    persona?: Persona;
    brief: ProjectBrief | null;
    profile: WriterProfile;
  },
): Promise<NoteVerdict | null> {
  const state = buildNoteState({
    note: input.note.slice(0, 8000),
    quote: input.quote || input.draft.slice(0, 16_000),
    draftExcerpt: input.draft.slice(0, 24_000),
    brief: input.brief,
    persona: input.persona ? JSON.stringify(input.persona) : undefined,
    writerProfile: input.profile,
  });
  const questions = buildNoteQuestions({
    hasConstraints: !!state.constraints,
    hasPersonaVoice: !!input.persona?.voice,
    hasAvoidances: !!input.persona?.avoidances?.length,
    hasWriterFacts: !!state.writerFacts,
    hasFeedbackPreferences: !!state.feedbackPreferences,
  });
  // An unanchored note cannot honestly be checked for misquoting a particular passage.
  if (!input.quote || !input.draft.includes(input.quote))
    delete questions.misquotesPassage;
  try {
    const result = await call({ state, questions });
    if (
      !result.ok ||
      !result.answers ||
      Object.entries(questions).some(
        ([id, question]) =>
          (result.answers?.[id] as SystemOneAnswer | undefined)?.type !==
          question.type,
      )
    )
      return null;
    return readNoteVerdict(result.answers as Record<string, SystemOneAnswer>);
  } catch {
    return null;
  }
}
import { capturePostHogEvent } from "./posthog-context";
import { getRuntimeFeatures } from "./feature-flags";
import {
  createAiTraceId,
  deterministicEvalProperties,
  serializeAiContent,
  type AiContentMode,
  type AiUsage,
} from "./ai-deterministic-evals";

export interface AiEvalCapture {
  feature: string;
  provider: string;
  model: string;
  system?: string;
  prompt: string;
  output?: string;
  latencyMs: number;
  temperature?: number;
  maxTokens?: number;
  traceId?: string;
  sessionId?: string;
  folioId?: string;
  editorialActionId?: string;
  spanName?: string;
  error?: unknown;
  usage?: AiUsage;
  contentMode?: AiContentMode;
  evalSignals?: Record<string, unknown>;
}

function countWords(text: string | undefined): number {
  return text?.trim().split(/\s+/).filter(Boolean).length ?? 0;
}

export async function captureAiGeneration({
  feature,
  provider,
  model,
  system,
  prompt,
  output,
  latencyMs,
  temperature,
  maxTokens,
  traceId: explicitTraceId,
  sessionId,
  folioId,
  editorialActionId,
  spanName,
  error,
  usage,
  contentMode = "redacted",
  evalSignals,
}: AiEvalCapture): Promise<string> {
  const resolvedTraceId = explicitTraceId ?? createAiTraceId(feature);
  await capturePostHogEvent(
    "$ai_generation",
    buildAiGenerationProperties({
      feature,
      provider,
      model,
      system,
      prompt,
      output,
      latencyMs,
      temperature,
      maxTokens,
      traceId: resolvedTraceId,
      sessionId,
      folioId,
      editorialActionId,
      spanName,
      error,
      usage,
      contentMode,
      evalSignals,
    }),
  );
  return resolvedTraceId;
}

export function buildAiGenerationProperties({
  feature,
  provider,
  model,
  system,
  prompt,
  output,
  latencyMs,
  temperature,
  maxTokens,
  traceId: explicitTraceId,
  sessionId,
  folioId,
  editorialActionId,
  spanName,
  error,
  usage,
  contentMode = "redacted",
  evalSignals,
}: AiEvalCapture): Record<string, unknown> {
  const features = getRuntimeFeatures();
  const resolvedTraceId = explicitTraceId ?? createAiTraceId(feature);
  const inputTextLength = (system?.length ?? 0) + prompt.length;
  return {
    $ai_trace_id: resolvedTraceId,
    $ai_session_id: sessionId,
    $ai_span_id: createAiTraceId(`${feature}:generation`),
    $ai_span_name: spanName ?? feature,
    $ai_model: model,
    $ai_provider: provider,
    $ai_input: [
      ...(system
        ? [{ role: "system", content: serializeAiContent(system, contentMode) }]
        : []),
      { role: "user", content: serializeAiContent(prompt, contentMode) },
    ],
    $ai_output_choices: output
      ? [
          {
            role: "assistant",
            content: serializeAiContent(output, contentMode),
          },
        ]
      : [],
    $ai_input_tokens: usage?.inputTokens,
    $ai_output_tokens: usage?.outputTokens,
    $ai_latency: latencyMs / 1000,
    $ai_temperature: temperature,
    $ai_max_tokens: maxTokens,
    $ai_is_error: !!error,
    $ai_error:
      error instanceof Error
        ? { message: error.message, name: error.name }
        : error
          ? String(error)
          : undefined,
    twyne_feature: feature,
    twyne_runtime_pricing_flag: features.pricing,
    twyne_runtime_local_ai_flag: features.localAi,
    twyne_output_words: countWords(output),
    twyne_prompt_words: countWords(prompt) + countWords(system),
    twyne_content_mode: contentMode,
    twyne_input_chars: inputTextLength,
    twyne_output_chars: output?.length ?? 0,
    twyne_folio_id: folioId,
    twyne_editorial_action_id: editorialActionId,
    ...deterministicEvalProperties(output, evalSignals),
    ...evalSignals,
  };
}
/**
 * Pure, content-agnostic checks for AI generation telemetry.
 *
 * These checks are guardrails, not quality judges. They make malformed
 * structured responses and broken protocols visible to PostHog without
 * turning an event property into an LLM evaluation result.
 */

export const AI_EVALUATION_VERSION = 1 as const;
export const MAX_AI_CONTENT_CHARS = 6000;

export type AiContentMode = "redacted" | "full";

export interface AiUsage {
  inputTokens?: number;
  outputTokens?: number;
  totalTokens?: number;
  cacheReadTokens?: number;
  cacheWriteTokens?: number;
  reasoningTokens?: number;
}

export interface DeterministicAiChecks {
  structuredOutput: boolean | null;
  scoreRange: boolean | null;
  protocol: boolean | null;
  citationIntegrity: boolean | null;
  status: "pass" | "fail" | "not_applicable";
}

export function createAiTraceId(feature: string): string {
  const uuid =
    typeof crypto !== "undefined" && "randomUUID" in crypto
      ? crypto.randomUUID()
      : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${feature}:${uuid}`;
}

export function clampAiContent(text: string | undefined): string | undefined {
  if (text === undefined) return undefined;
  if (text.length <= MAX_AI_CONTENT_CHARS) return text;
  return `${text.slice(0, MAX_AI_CONTENT_CHARS)}\n\n[truncated]`;
}

export function serializeAiContent(
  text: string | undefined,
  mode: AiContentMode,
): string | undefined {
  if (text === undefined) return undefined;
  return mode === "full" ? clampAiContent(text) : "[redacted]";
}

export function normalizeAiUsage(value: unknown): AiUsage | undefined {
  if (!value || typeof value !== "object") return undefined;
  const raw = value as Record<string, unknown>;
  const details =
    raw.inputTokenDetails && typeof raw.inputTokenDetails === "object"
      ? (raw.inputTokenDetails as Record<string, unknown>)
      : {};
  const outputDetails =
    raw.outputTokenDetails && typeof raw.outputTokenDetails === "object"
      ? (raw.outputTokenDetails as Record<string, unknown>)
      : {};
  const number = (candidate: unknown): number | undefined =>
    typeof candidate === "number" && Number.isFinite(candidate)
      ? Math.max(0, Math.floor(candidate))
      : undefined;
  const usage: AiUsage = {
    inputTokens: number(raw.inputTokens),
    outputTokens: number(raw.outputTokens),
    totalTokens: number(raw.totalTokens),
    cacheReadTokens: number(raw.cachedInputTokens ?? details.cacheReadTokens),
    cacheWriteTokens: number(details.cacheWriteTokens),
    reasoningTokens: number(
      raw.reasoningTokens ?? outputDetails.reasoningTokens,
    ),
  };
  return Object.values(usage).some((entry) => entry !== undefined)
    ? usage
    : undefined;
}

function parseJsonObject(text: string): Record<string, unknown> | null {
  const candidates = [
    text.trim(),
    text
      .trim()
      .replace(/^```(?:json)?/i, "")
      .replace(/```$/, "")
      .trim(),
    text.match(/\{[\s\S]*\}/)?.[0] ?? "",
  ];
  for (const candidate of candidates) {
    if (!candidate) continue;
    try {
      const value: unknown = JSON.parse(candidate);
      if (value && typeof value === "object" && !Array.isArray(value)) {
        return value as Record<string, unknown>;
      }
    } catch {
      // Try the next tolerant candidate.
    }
  }
  return null;
}

function structuredOutputCheck(
  output: string,
  expectedFormat: unknown,
): { valid: boolean; scoreRange: boolean | null } | null {
  if (typeof expectedFormat !== "string") return null;
  const parsed = parseJsonObject(output);
  if (!parsed) return { valid: false, scoreRange: null };

  switch (expectedFormat) {
    case "json_score_rationale": {
      const score = parsed.score;
      const validScore =
        typeof score === "number" &&
        Number.isInteger(score) &&
        score >= 1 &&
        score <= 10;
      return {
        valid:
          validScore &&
          typeof parsed.rationale === "string" &&
          !!parsed.rationale.trim(),
        scoreRange: validScore,
      };
    }
    case "json_rewrite":
      return {
        valid:
          typeof parsed.replacement === "string" && !!parsed.replacement.trim(),
        scoreRange: null,
      };
    case "json_dossier_observations":
      return { valid: Array.isArray(parsed.observations), scoreRange: null };
    case "json_criteria":
      return { valid: Array.isArray(parsed.criteria), scoreRange: null };
    default:
      return { valid: true, scoreRange: null };
  }
}

function protocolCheck(
  output: string,
  signals: Record<string, unknown>,
): boolean | null {
  const required = signals.twyne_required_protocol_markers;
  if (Array.isArray(required)) {
    return required.every(
      (marker) => typeof marker === "string" && output.includes(marker),
    );
  }
  const any = signals.twyne_any_protocol_markers;
  if (Array.isArray(any)) {
    return any.some(
      (marker) => typeof marker === "string" && output.includes(marker),
    );
  }
  return null;
}

function citationCheck(
  output: string,
