471	/**
472	 * Run the five editors over the new material. BYOK first, then the server
473	 * action — the same order the Cast panel uses, so the background room and the
474	 * explicit convene never disagree about which provider is in play.
475	 *
476	 * Returns an empty array rather than throwing when no provider is reachable:
477	 * a background pass that quietly does nothing is correct, while an error toast
478	 * the writer never asked for is not.
479	 */
480	async function conveneQuietly(input: {
481	  draftText: string;
482	  newMaterial: string;
483	  trajectory: string;
484	  brief: ProjectBrief | null;
485	  client: ConvexClient | null;
486	  personas: Persona[];
487	}): Promise<QuietResponse[]> {
488	  const settings = await getCachedAiSettings();
489	  const writerProfile = (await loadWriterSettingsFromIdb()).profile;
490	
491	  if (hasConfiguredAiProvider(settings)) {
492	    const results = await Promise.all(
493	      input.personas.map(async (p) => {
494	        const res = await runClientAgent(
495	          "persona-feedback",
496	          {
497	            persona: toAgentPersona(p),
498	            brief: input.brief,
499	            draftText: input.draftText,
500	            writerProfile,
501	            newMaterial: input.newMaterial,
502	            trajectory: input.trajectory,
503	            instruction: "feedback" as const,
504	          },
505	          settings,
506	        );
507	        if (!res || !res.text.trim() || res.provider === "local") return null;
508	        const note: QuietResponse = {
509	          personaId: p.id,
510	          text: res.text,
511	          type: res.type,
512	          provider: res.provider,
513	          anchor: res.anchor,
514	        };
515	        return note;
516	      }),
517	    );
518	    return results.filter((r): r is QuietResponse => r !== null);
519	  }
520	
521	  if (!input.client) return [];
522	  const result = (await input.client.action(api.agents.conveneRoom, {
523	    responseLocale: currentModelLocale(),
524	    personas: input.personas.map(toAgentPersona),
525	    brief: input.brief ?? null,
526	    draftText: input.draftText,
527	    writerProfile,
528	    newMaterial: input.newMaterial,
529	    trajectory: input.trajectory,
530	  })) as QuietResponse[];
531	  return result.filter((r) => r.text.trim() && r.provider !== "local");
532	}
