676	/* ── Initiation ────────────────────────────────────────────────── */
677	
678	/**
679	 * What the gate is allowed to do with a verdict, which depends entirely on who
680	 * asked for it.
681	 *
682	 * `filter` — the room was convened, so the writer asked for notes and not for
683	 * a critique of the notes. The gate may suppress and retry silently; that is
684	 * the service being performed.
685	 *
686	 * `annotate` — the writer is looking at a note and asked what we make of it.
687	 * Hiding it now would be answering a question they did not ask, and would hide
688	 * the very thing they pointed at. Nothing is suppressed; the verdict becomes a
689	 * label beside the note.
690	 *
691	 * The distinction exists because a user-initiated review and a generation-time
692	 * gate share all of their scoring and none of their authority.
693	 */
694	export type NoteGateMode = "filter" | "annotate";
695	
696	export interface NoteGateAction {
697	  /** Whether the writer sees the note at all. */
698	  show: boolean;
699	  /** What a retry should repair, or `null` to accept as-is. */
700	  rewrite: RewriteKind | null;
701	}
702	
703	/**
704	 * Policy over a cached verdict. Pure and synchronous, like `viewRubricGrade`:
705	 * a writer moving a threshold re-renders from the verdict already in hand, and
706	 * no judgement is ever re-run to answer a slider.
707	 */
708	export function noteAction(
709	  verdict: NoteVerdict,
710	  mode: NoteGateMode,
711	  attempt = 0,
712	): NoteGateAction {
713	  if (mode === "annotate") {
714	    // Never hide what the writer explicitly pointed at.
715	    return { show: true, rewrite: null };
716	  }
717	  if (verdict.pass && verdict.rewriteKind === null) {
718	    return { show: true, rewrite: null };
719	  }
720	  if (attempt >= MAX_REWRITES) {
721	    // Out of retries. A vetoed note is withheld — it breaks something the
722	    // writer declared — but a merely mediocre one is still shown, because a
723	    // weak note the writer can ignore beats a silent room.
724	    return { show: !verdict.vetoed, rewrite: null };
725	  }
726	  return { show: !verdict.vetoed, rewrite: verdict.rewriteKind };
727	}
728	
729	/**
730	 * Keep the best attempt, not the last one. A rewrite can come back worse, and
731	 * having paid for both there is no reason to show the worse one. Vetoed
732	 * attempts always lose to un-vetoed ones regardless of score.
733	 */
734	export function bestAttempt<T>(
735	  attempts: { note: T; verdict: NoteVerdict }[],
736	): { note: T; verdict: NoteVerdict } | null {
737	  if (attempts.length === 0) return null;
738	  return attempts.reduce((best, a) => {
739	    if (best.verdict.vetoed !== a.verdict.vetoed) {
740	      return best.verdict.vetoed ? a : best;
741	    }
742	    return a.verdict.overall > best.verdict.overall ? a : best;
743	  });
744	}
