 78	/** Balanced rotations reduce arm/model position bias without selecting on outcomes. */
 79	export function benchmarkSchedule(caseCount: number, modelCount: number, repetitions: number): ScheduledTrial[] {
 80	  const schedule: ScheduledTrial[] = [];
 81	  for (let repetition = 0; repetition < repetitions; repetition++) {
 82	    for (let caseIndex = 0; caseIndex < caseCount; caseIndex++) {
 83	      const offset = caseIndex + repetition;
 84	      const arms = BENCHMARK_ARMS.map((_, index) => BENCHMARK_ARMS[(index + offset) % BENCHMARK_ARMS.length]!);
 85	      for (let slot = 0; slot < modelCount; slot++) {
 86	        const modelIndex = (slot + offset) % modelCount;
 87	        for (const arm of repetition % 2 === 0 ? arms : [...arms].reverse()) schedule.push({ caseIndex, modelIndex, arm, repetition });
 88	      }
 89	    }
 90	  }
 91	  return schedule;
 92	}
