        confidence: feedbackAdherenceAnswer.confidence,
        nearestLevel: nearest(
          feedbackAdherenceAnswer.legend,
          feedbackAdherenceAnswer.score,
        ),
      }
    : null;

  const constraintVetoed =
    violationRisk !== null && violationRisk > thresholds.maxViolationRisk;
  const quoteVetoed = quoteRisk !== null && quoteRisk > thresholds.maxQuoteRisk;
  const factVetoed =
    factViolationRisk !== null &&
    factViolationRisk > thresholds.maxFactViolationRisk;
  const vetoed = constraintVetoed || quoteVetoed || factVetoed;

  const reasons: string[] = [];
  if (constraintVetoed) {
    reasons.push("Conflicts with a constraint stated in the brief.");
  }
  if (quoteVetoed) {
    reasons.push("Misquotes the passage it comments on.");
  }
  if (factVetoed) {
    reasons.push(
      "Contradicts or misrepresents the writer's stated facts or background context.",
    );
  }
  for (const [dim, d] of Object.entries(dimensions) as [
    NoteDimension,
    NoteDimensionScore,
  ][]) {
    if (d.score < thresholds.minDimension) {
      // The level description, not the number: "Vague — gestures at a problem
      // without locating it" tells a model what to fix. "helpful: 2.1" does not.
      reasons.push(`${dim}: ${d.nearestLevel}`);
    }
  }
  if (!vetoed && overall < thresholds.minOverall && reasons.length === 0) {
    reasons.push("Below the quality bar overall without one clear weak spot.");
  }

  const substanceFailed =
    overall < thresholds.minOverall ||
    present.some((d) => d.score < thresholds.minDimension);
  const voiceFailed =
    (adherence !== null && adherence.score < thresholds.minAdherence) ||
    (breaksAvoidance !== null && breaksAvoidance > thresholds.maxAvoidanceRisk);
  const factsFailed =
    factVetoed ||
    (factAdherence !== null &&
      factAdherence.score < thresholds.minFactAdherence);
  const preferenceFailed =
    (preferenceViolationRisk !== null &&
      preferenceViolationRisk > thresholds.maxPreferenceViolationRisk) ||
    (feedbackAdherence !== null &&
      feedbackAdherence.score < thresholds.minFeedbackAdherence);

  // Voice, fact, and preference reasons are recorded after quality
  if (voiceFailed) {
    if (
      breaksAvoidance !== null &&
      breaksAvoidance > thresholds.maxAvoidanceRisk
    ) {
      reasons.push("Does something this editor is described as never doing.");
    } else if (adherence) {
      reasons.push(`voice: ${adherence.nearestLevel}`);
    }
  }
  if (factsFailed && !factVetoed && factAdherence) {
    reasons.push(`facts: ${factAdherence.nearestLevel}`);
  }
  if (preferenceFailed) {
    if (
      preferenceViolationRisk !== null &&
      preferenceViolationRisk > thresholds.maxPreferenceViolationRisk
    ) {
      reasons.push(
        "Disregards how the writer likes to receive feedback or engages in declared avoidances.",
      );
    } else if (feedbackAdherence) {
      reasons.push(`feedback style: ${feedbackAdherence.nearestLevel}`);
    }
  }

  const rewriteKind: RewriteKind | null = constraintVetoed
    ? "constraint"
    : quoteVetoed
      ? "accuracy"
      : factVetoed || factsFailed
        ? "facts"
        : preferenceFailed
          ? "preference"
          : substanceFailed && voiceFailed
            ? "both"
            : substanceFailed
              ? "substance"
              : voiceFailed
                ? "voice"
                : null;

  return {
    dimensions,
    overall,
    violationRisk,
    quoteRisk,
    adherence,
    breaksAvoidance,
    factAdherence,
    factViolationRisk,
    feedbackAdherence,
    preferenceViolationRisk,
    vetoed,
    pass:
      !vetoed &&
      overall >= thresholds.minOverall &&
      present.every((d) => d.score >= thresholds.minDimension),
    reasons,
    rewriteKind,
  };
}

/* ── Rewriting ─────────────────────────────────────────────────── */

/**
 * At most two retries. A model that has failed the same gate three times is
 * not going to pass it on the fourth; it has misread the passage, and burning
 * further frontier calls on it costs real money for no gain.
 */
export const MAX_REWRITES = 2;

/**
 * Turn a failed verdict into an instruction. Phrased as what to do rather than
 * what went wrong, because "be more specific about which sentence" produces a
 * better second attempt than "your note scored 2.1 on actionable".
 *
 * The instruction is routed by `rewriteKind`. Asking a model to fix its voice
 * when the substance was the problem reliably produces a better-dressed
 * version of the same empty note, and asking it to fix substance when only the
 * voice slipped throws away a good observation.
 */
export function rewriteInstruction(verdict: NoteVerdict): string {
  const lines = ["Revise the note. It did not meet the bar:"];
  for (const reason of verdict.reasons) lines.push(`- ${reason}`);

  switch (verdict.rewriteKind) {
    case "constraint":
      lines.push(
        "Rewrite so it respects the writer's stated constraints. If the point cannot be made without breaking one, drop it and make a different point about this passage.",
      );
      break;
    case "accuracy":
      lines.push(
        "Quote the passage exactly as written. Do not put words in the draft's mouth: paraphrase only without quotation marks, and never treat a paraphrase as evidence for the point.",
      );
      break;
    case "facts":
      lines.push(
        "Rewrite so it adheres strictly to the writer's stated personal facts and background context. Do not make false assumptions or contradict what the writer established.",
      );
      break;
    case "preference":
      lines.push(
        "Rewrite so it honours how the writer likes to receive feedback: match their requested feedback pressure, tone, and focus areas, and observe their guidance.",
      );
      break;
    case "voice":
      lines.push(
        "Keep the observation exactly as it is — it is sound. Rewrite only the manner so it reads as this editor: their diction, their rhythm, their characteristic moves. Do not soften or broaden the point to achieve it.",
      );
      break;
    case "both":
      lines.push(
        "Name the specific sentence or phrase, say what is wrong with it, and say what to do instead. Then make sure it reads as this editor rather than a generic reviewer. Do not restate the passage.",
      );
      break;
    default:
      lines.push(
        "Name the specific sentence or phrase, say what is wrong with it, and say what to do instead. Do not restate the passage.",
      );
  }
  return lines.join("\n");
}

/**
 * Convenience helper to build questions specifically checking adherence to writer facts
 * and feedback preferences.
 */
export function buildAdherenceQuestions(
  profile: WriterProfile,
): Record<string, SystemOneQuestion> {
  return buildNoteQuestions({
    hasConstraints: false,
    hasWriterFacts: Boolean(profile.personalFacts?.trim()),
    hasFeedbackPreferences: true,
  });
}
import type { Persona, ProjectBrief, WriterProfile } from "../types";
import {
  buildNoteQuestions,
  buildNoteState,
  readNoteVerdict,
  type NoteVerdict,
} from "./note-gate";
import type { SystemOneAnswer } from "./system-one";
import type { WritingLensCaller } from "./writing-lenses";

/** Missing answers are unavailable, never a synthetic pass or a veto. */
export async function reviewEditorialNote(
  call: WritingLensCaller,
  input: {
    note: string;
    quote?: string;
    draft: string;
    persona?: Persona;
    brief: ProjectBrief | null;
    profile: WriterProfile;
  },
): Promise<NoteVerdict | null> {
  const state = buildNoteState({
    note: input.note.slice(0, 8000),
    quote: input.quote || input.draft.slice(0, 16_000),
    draftExcerpt: input.draft.slice(0, 24_000),
    brief: input.brief,
    persona: input.persona ? JSON.stringify(input.persona) : undefined,
    writerProfile: input.profile,
  });
  const questions = buildNoteQuestions({
    hasConstraints: !!state.constraints,
    hasPersonaVoice: !!input.persona?.voice,
    hasAvoidances: !!input.persona?.avoidances?.length,
    hasWriterFacts: !!state.writerFacts,
    hasFeedbackPreferences: !!state.feedbackPreferences,
  });
  // An unanchored note cannot honestly be checked for misquoting a particular passage.
  if (!input.quote || !input.draft.includes(input.quote))
    delete questions.misquotesPassage;
  try {
    const result = await call({ state, questions });
    if (
      !result.ok ||
      !result.answers ||
      Object.entries(questions).some(
        ([id, question]) =>
          (result.answers?.[id] as SystemOneAnswer | undefined)?.type !==
          question.type,
      )
    )
      return null;
    return readNoteVerdict(result.answers as Record<string, SystemOneAnswer>);
  } catch {
    return null;
  }
}
import { capturePostHogEvent } from "./posthog-context";
import { getRuntimeFeatures } from "./feature-flags";
import {
  createAiTraceId,
  deterministicEvalProperties,
  serializeAiContent,
  type AiContentMode,
  type AiUsage,
} from "./ai-deterministic-evals";

export interface AiEvalCapture {
  feature: string;
  provider: string;
  model: string;
  system?: string;
  prompt: string;
  output?: string;
  latencyMs: number;
  temperature?: number;
  maxTokens?: number;
  traceId?: string;
  sessionId?: string;
  folioId?: string;
  editorialActionId?: string;
  spanName?: string;
  error?: unknown;
  usage?: AiUsage;
  contentMode?: AiContentMode;
  evalSignals?: Record<string, unknown>;
}

function countWords(text: string | undefined): number {
  return text?.trim().split(/\s+/).filter(Boolean).length ?? 0;
}

export async function captureAiGeneration({
  feature,
  provider,
  model,
  system,
  prompt,
  output,
  latencyMs,
  temperature,
  maxTokens,
  traceId: explicitTraceId,
  sessionId,
  folioId,
  editorialActionId,
  spanName,
  error,
  usage,
  contentMode = "redacted",
  evalSignals,
}: AiEvalCapture): Promise<string> {
  const resolvedTraceId = explicitTraceId ?? createAiTraceId(feature);
  await capturePostHogEvent(
    "$ai_generation",
    buildAiGenerationProperties({
      feature,
      provider,
      model,
      system,
      prompt,
      output,
      latencyMs,
      temperature,
      maxTokens,
      traceId: resolvedTraceId,
      sessionId,
      folioId,
      editorialActionId,
      spanName,
      error,
      usage,
      contentMode,
      evalSignals,
    }),
  );
  return resolvedTraceId;
}

export function buildAiGenerationProperties({
  feature,
  provider,
  model,
  system,
  prompt,
  output,
  latencyMs,
  temperature,
  maxTokens,
  traceId: explicitTraceId,
  sessionId,
  folioId,
  editorialActionId,
  spanName,
  error,
  usage,
  contentMode = "redacted",
  evalSignals,
}: AiEvalCapture): Record<string, unknown> {
  const features = getRuntimeFeatures();
  const resolvedTraceId = explicitTraceId ?? createAiTraceId(feature);
  const inputTextLength = (system?.length ?? 0) + prompt.length;
  return {
    $ai_trace_id: resolvedTraceId,
    $ai_session_id: sessionId,
    $ai_span_id: createAiTraceId(`${feature}:generation`),
    $ai_span_name: spanName ?? feature,
    $ai_model: model,
    $ai_provider: provider,
    $ai_input: [
      ...(system
        ? [{ role: "system", content: serializeAiContent(system, contentMode) }]
        : []),
      { role: "user", content: serializeAiContent(prompt, contentMode) },
    ],
    $ai_output_choices: output
      ? [
          {
            role: "assistant",
            content: serializeAiContent(output, contentMode),
          },
        ]
      : [],
    $ai_input_tokens: usage?.inputTokens,
    $ai_output_tokens: usage?.outputTokens,
    $ai_latency: latencyMs / 1000,
    $ai_temperature: temperature,
    $ai_max_tokens: maxTokens,
    $ai_is_error: !!error,
    $ai_error:
      error instanceof Error
        ? { message: error.message, name: error.name }
        : error
          ? String(error)
          : undefined,
    twyne_feature: feature,
    twyne_runtime_pricing_flag: features.pricing,
    twyne_runtime_local_ai_flag: features.localAi,
    twyne_output_words: countWords(output),
    twyne_prompt_words: countWords(prompt) + countWords(system),
    twyne_content_mode: contentMode,
    twyne_input_chars: inputTextLength,
    twyne_output_chars: output?.length ?? 0,
    twyne_folio_id: folioId,
    twyne_editorial_action_id: editorialActionId,
    ...deterministicEvalProperties(output, evalSignals),
    ...evalSignals,
  };
}
/**
 * Pure, content-agnostic checks for AI generation telemetry.
 *
 * These checks are guardrails, not quality judges. They make malformed
 * structured responses and broken protocols visible to PostHog without
 * turning an event property into an LLM evaluation result.
 */

export const AI_EVALUATION_VERSION = 1 as const;
export const MAX_AI_CONTENT_CHARS = 6000;

export type AiContentMode = "redacted" | "full";

export interface AiUsage {
  inputTokens?: number;
  outputTokens?: number;
  totalTokens?: number;
  cacheReadTokens?: number;
  cacheWriteTokens?: number;
  reasoningTokens?: number;
}

export interface DeterministicAiChecks {
  structuredOutput: boolean | null;
  scoreRange: boolean | null;
  protocol: boolean | null;
  citationIntegrity: boolean | null;
  status: "pass" | "fail" | "not_applicable";
}

export function createAiTraceId(feature: string): string {
  const uuid =
    typeof crypto !== "undefined" && "randomUUID" in crypto
      ? crypto.randomUUID()
      : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${feature}:${uuid}`;
}

export function clampAiContent(text: string | undefined): string | undefined {
  if (text === undefined) return undefined;
  if (text.length <= MAX_AI_CONTENT_CHARS) return text;
  return `${text.slice(0, MAX_AI_CONTENT_CHARS)}\n\n[truncated]`;
}

export function serializeAiContent(
  text: string | undefined,
  mode: AiContentMode,
): string | undefined {
  if (text === undefined) return undefined;
  return mode === "full" ? clampAiContent(text) : "[redacted]";
}

export function normalizeAiUsage(value: unknown): AiUsage | undefined {
  if (!value || typeof value !== "object") return undefined;
  const raw = value as Record<string, unknown>;
  const details =
    raw.inputTokenDetails && typeof raw.inputTokenDetails === "object"
      ? (raw.inputTokenDetails as Record<string, unknown>)
      : {};
  const outputDetails =
    raw.outputTokenDetails && typeof raw.outputTokenDetails === "object"
      ? (raw.outputTokenDetails as Record<string, unknown>)
      : {};
  const number = (candidate: unknown): number | undefined =>
    typeof candidate === "number" && Number.isFinite(candidate)
      ? Math.max(0, Math.floor(candidate))
      : undefined;
  const usage: AiUsage = {
    inputTokens: number(raw.inputTokens),
    outputTokens: number(raw.outputTokens),
    totalTokens: number(raw.totalTokens),
    cacheReadTokens: number(raw.cachedInputTokens ?? details.cacheReadTokens),
    cacheWriteTokens: number(details.cacheWriteTokens),
    reasoningTokens: number(
      raw.reasoningTokens ?? outputDetails.reasoningTokens,
    ),
  };
  return Object.values(usage).some((entry) => entry !== undefined)
    ? usage
    : undefined;
}

function parseJsonObject(text: string): Record<string, unknown> | null {
  const candidates = [
    text.trim(),
    text
      .trim()
      .replace(/^```(?:json)?/i, "")
      .replace(/```$/, "")
      .trim(),
    text.match(/\{[\s\S]*\}/)?.[0] ?? "",
  ];
  for (const candidate of candidates) {
    if (!candidate) continue;
    try {
      const value: unknown = JSON.parse(candidate);
      if (value && typeof value === "object" && !Array.isArray(value)) {
        return value as Record<string, unknown>;
      }
    } catch {
      // Try the next tolerant candidate.
    }
  }
  return null;
}

function structuredOutputCheck(
  output: string,
  expectedFormat: unknown,
): { valid: boolean; scoreRange: boolean | null } | null {
  if (typeof expectedFormat !== "string") return null;
  const parsed = parseJsonObject(output);
  if (!parsed) return { valid: false, scoreRange: null };

  switch (expectedFormat) {
    case "json_score_rationale": {
      const score = parsed.score;
      const validScore =
        typeof score === "number" &&
        Number.isInteger(score) &&
        score >= 1 &&
        score <= 10;
      return {
        valid:
          validScore &&
          typeof parsed.rationale === "string" &&
          !!parsed.rationale.trim(),
        scoreRange: validScore,
      };
    }
    case "json_rewrite":
      return {
        valid:
          typeof parsed.replacement === "string" && !!parsed.replacement.trim(),
        scoreRange: null,
      };
    case "json_dossier_observations":
      return { valid: Array.isArray(parsed.observations), scoreRange: null };
    case "json_criteria":
      return { valid: Array.isArray(parsed.criteria), scoreRange: null };
    default:
      return { valid: true, scoreRange: null };
  }
}

function protocolCheck(
  output: string,
  signals: Record<string, unknown>,
): boolean | null {
  const required = signals.twyne_required_protocol_markers;
  if (Array.isArray(required)) {
    return required.every(
      (marker) => typeof marker === "string" && output.includes(marker),
    );
  }
  const any = signals.twyne_any_protocol_markers;
  if (Array.isArray(any)) {
    return any.some(
      (marker) => typeof marker === "string" && output.includes(marker),
    );
  }
  return null;
}

function citationCheck(
  output: string,
  signals: Record<string, unknown>,
): boolean | null {
  if (signals.twyne_requires_sources !== true) return null;
  if (/javascript:/i.test(output)) return false;
  const urls = output.match(/https?:\/\/[^\s)<>]+/gi) ?? [];
  const bracketCitations = output.match(/\[\d+\]/g) ?? [];
  return urls.length > 0 || bracketCitations.length > 0;
}

export function evaluateAiOutput({
  output,
  evalSignals = {},
}: {
  output?: string;
  evalSignals?: Record<string, unknown>;
}): DeterministicAiChecks {
  const text = output ?? "";
  const structured = structuredOutputCheck(
    text,
    evalSignals.twyne_expected_format,
  );
  const checks: DeterministicAiChecks = {
    structuredOutput: structured?.valid ?? null,
    scoreRange: structured?.scoreRange ?? null,
    protocol: protocolCheck(text, evalSignals),
    citationIntegrity: citationCheck(text, evalSignals),
    status: "not_applicable",
  };
  const applicable = [
    checks.structuredOutput,
    checks.scoreRange,
    checks.protocol,
    checks.citationIntegrity,
  ].filter((check): check is boolean => check !== null);
  checks.status =
    applicable.length === 0
      ? "not_applicable"
      : applicable.every(Boolean)
        ? "pass"
        : "fail";
  return checks;
}

export function deterministicEvalProperties(
  output: string | undefined,
  evalSignals: Record<string, unknown> = {},
): Record<string, unknown> {
  const checks = evaluateAiOutput({ output, evalSignals });
  return {
    twyne_eval_version: AI_EVALUATION_VERSION,
    twyne_eval_status: checks.status,
    twyne_eval_structured_output_valid: checks.structuredOutput,
    twyne_eval_score_range_valid: checks.scoreRange,
    twyne_eval_protocol_valid: checks.protocol,
    twyne_eval_citation_integrity_valid: checks.citationIntegrity,
  };
}

