678	/**
679	 * What the gate is allowed to do with a verdict, which depends entirely on who
680	 * asked for it.
681	 *
682	 * `filter` — the room was convened, so the writer asked for notes and not for
683	 * a critique of the notes. The gate may suppress and retry silently; that is
684	 * the service being performed.
685	 *
686	 * `annotate` — the writer is looking at a note and asked what we make of it.
687	 * Hiding it now would be answering a question they did not ask, and would hide
688	 * the very thing they pointed at. Nothing is suppressed; the verdict becomes a
689	 * label beside the note.
690	 *
691	 * The distinction exists because a user-initiated review and a generation-time
692	 * gate share all of their scoring and none of their authority.
693	 */
694	export type NoteGateMode = "filter" | "annotate";
695	
696	export interface NoteGateAction {
697	  /** Whether the writer sees the note at all. */
698	  show: boolean;
699	  /** What a retry should repair, or `null` to accept as-is. */
700	  rewrite: RewriteKind | null;
701	}
