  const uncertain = checks.filter((check) => check.status === "unknown");
  const status: EditorialPolicyStatus = failed.length
    ? "fail"
    : uncertain.length
      ? "unknown"
      : "pass";

  return {
    version: EDITORIAL_POLICY_VERSION,
    status,
    checks,
    failed,
    uncertain,
  };
}

