/// <reference types="vite/client" />
/**
 * Prompt loader. Each `.md` file in `prompts/` becomes a string accessible
 * here. Frontmatter (between `---` fences at the top of a file) is parsed
 * into a small record; the body becomes the template body.
 *
 * `{name}` placeholders in the body are substituted by `renderPrompt()`
 * — language-agnostic, zero-dep, matches what every LLM prompt tutorial
 * already writes as "placeholder syntax". Unresolved placeholders are left
 * literal so a forgotten rename shows up as `{goal}` in the prompt
 * instead of silently dropping the line.
 *
 * Three runtime contexts hit this file and each must work:
 *   1. Vite-bundled browser code (`src/utils/ai-client.ts`): `import.meta.glob`
 *      is inlined at build time, so this module exports a fully resolved
 *      `prompts` map.
 *   2. Convex backend (`convex/agentPrompts.ts`): the same `import.meta.glob`
 *      is resolved by Convex's Vite-based bundler the same way. No `"use node"`
 *      needed; the strings come in as constants.
 *   3. bun:test (`:test` files): `import.meta.glob` is undefined. The fallback
 *      below reads `.md` files from the repo's `prompts/` directory using
 *      `node:fs`, so unit tests can render and assert against the same text.
 */

export interface PromptFrontmatter {
  /** Author-supplied short description for prompt-learning notes. */
  notes?: string;
  /** Free-form version string ("1", "1.2", "2024-10-08"). */
  version?: string;
  /** Suggested model choice. Treated as advisory on the BYOK path. */
  model?: string;
  /** Last optimization pass — written by evals/optimize-prompts.py. */
  lastOptimized?: string;
  /** Free-form anything else. Not consumed by the loader. */
  [key: string]: unknown;
}

export interface LoadedPrompt {
  /** Frontmatter at the top of the file, `{}` when absent. */
  frontmatter: PromptFrontmatter;
  /** Body text with the frontmatter stripped. Holds `{var}` placeholders. */
  body: string;
}

type RawModule = string | { default: string } | undefined;

/** Strip YAML-ish frontmatter from a markdown file body. */
function splitFrontmatter(raw: string): {
  frontmatter: PromptFrontmatter;
  body: string;
} {
  // Frontmatter must be the very first line, fenced by `---` on its own line
  // and closed with `---` on its own line. Keeps the loader honest: anything
  // that doesn't match is treated as pure body so we never silently drop text.
  if (!raw.startsWith("---")) return { frontmatter: {}, body: raw };
  // After the opening `---`, look for the closing fence `\n---`. The fence
  // is three `-`s; the next char should be a newline (or EOF) so the fence
  // sits on its own line.
  const closeSearch = raw.indexOf("\n---", 3);
  if (closeSearch < 0) return { frontmatter: {}, body: raw };
  const fenceEnd = closeSearch + 4; // covers "\n---"
  const afterFence = raw[fenceEnd]; // first char after the fence (or undefined)
  if (afterFence !== undefined && afterFence !== "\n") {
    return { frontmatter: {}, body: raw };
  }
  // Block between the two fences, excluding the opening `---`.
  const block = raw.slice(3, closeSearch).trim();
  const bodyStart = fenceEnd + (afterFence === "\n" ? 1 : 0);
  const body = raw.slice(bodyStart).replace(/^\n/, "");
  return { frontmatter: parseFrontmatterBlock(block), body };
}

/**
 * Tiny key-value frontmatter parser. Each non-empty line is `key: value`.
 * Values are unquoted strings; quoted values have the wrapping double or
 * single quotes stripped. Comments (`# …`) and blank lines are ignored. No
 * nested structures — frontmatter is intentionally minimal so a writer
 * can edit it without learning YAML.
 */
function parseFrontmatterBlock(block: string): PromptFrontmatter {
  const out: PromptFrontmatter = {};
  for (const rawLine of block.split("\n")) {
    const line = rawLine.trim();
    if (!line || line.startsWith("#")) continue;
    const colon = line.indexOf(":");
    if (colon < 1) continue;
    const key = line.slice(0, colon).trim();
    let value = line.slice(colon + 1).trim();
    if (value.length >= 2) {
      const first = value[0];
      const last = value[value.length - 1];
      if ((first === '"' && last === '"') || (first === "'" && last === "'")) {
        value = value.slice(1, -1);
      }
    }
    if (!key) continue;
    out[key] = value;
  }
  return out;
}

function unwrap(mod: RawModule): string {
  if (typeof mod === "string") return mod;
  if (mod && typeof mod === "object" && "default" in mod) {
    return String((mod as { default: unknown }).default ?? "");
  }
  return "";
}

/** Path → LoadedPrompt (relative to the repo's `prompts/` directory). */
const cache = new Map<string, LoadedPrompt>();

/**
 * Resolve a basename (e.g. `"persona-system"`) or a path-with-extension
 * (e.g. `"blocks/writer-profile"`) to the loaded prompt. Falls back to
 * reading from disk when running under bun:…1342 tokens truncated…Questions,
  buildNoteState,
  readNoteVerdict,
  type NoteVerdict,
} from "./note-gate";
import type { SystemOneAnswer } from "./system-one";
import type { WritingLensCaller } from "./writing-lenses";

/** Missing answers are unavailable, never a synthetic pass or a veto. */
export async function reviewEditorialNote(
  call: WritingLensCaller,
  input: {
    note: string;
    quote?: string;
    draft: string;
    persona?: Persona;
    brief: ProjectBrief | null;
    profile: WriterProfile;
  },
): Promise<NoteVerdict | null> {
  const state = buildNoteState({
    note: input.note.slice(0, 8000),
    quote: input.quote || input.draft.slice(0, 16_000),
    draftExcerpt: input.draft.slice(0, 24_000),
    brief: input.brief,
    persona: input.persona ? JSON.stringify(input.persona) : undefined,
    writerProfile: input.profile,
  });
  const questions = buildNoteQuestions({
    hasConstraints: !!state.constraints,
    hasPersonaVoice: !!input.persona?.voice,
    hasAvoidances: !!input.persona?.avoidances?.length,
    hasWriterFacts: !!state.writerFacts,
    hasFeedbackPreferences: !!state.feedbackPreferences,
  });
  // An unanchored note cannot honestly be checked for misquoting a particular passage.
  if (!input.quote || !input.draft.includes(input.quote))
    delete questions.misquotesPassage;
  try {
    const result = await call({ state, questions });
    if (
      !result.ok ||
      !result.answers ||
      Object.entries(questions).some(
        ([id, question]) =>
          (result.answers?.[id] as SystemOneAnswer | undefined)?.type !==
          question.type,
      )
    )
      return null;
    return readNoteVerdict(result.answers as Record<string, SystemOneAnswer>);
  } catch {
    return null;
  }
}

/* ── Verdict ───────────────────────────────────────────────────── */

export interface NoteDimensionScore {
  /** 0–10. */
  score: number;
  confidence: number;
  /** The level description the score landed nearest — the rewrite feedback. */
  nearestLevel: string;
}

export interface NoteVerdict {
  dimensions: Partial<Record<NoteDimension, NoteDimensionScore>>;
  /** Mean of the graded dimensions, 0–10. */
  overall: number;
  /** Probability the note breaks a stated constraint. */
  violationRisk: number | null;
  /** Probability the note misquotes the passage it comments on. */
  quoteRisk: number | null;
  /**
   * How much the note reads as its signatory. Deliberately outside
   * `dimensions`, so it cannot reach `overall` or `pass`.
   */
  adherence: NoteDimensionScore | null;
  /** Probability the note does something this editor declared they never do. */
  breaksAvoidance: number | null;
  /** How well the note adheres to the writer's stated facts and background context. */
  factAdherence: NoteDimensionScore | null;
  /** Probability the note contradicts or misrepresents stated facts. */
  factViolationRisk: number | null;
  /** How well the note adheres to how the writer likes feedback. */
  feedbackAdherence: NoteDimensionScore | null;
  /** Probability the note disregards feedback guidance. */
  preferenceViolationRisk: number | null;
  /** Vetoed on brief constraints or severe fact contradiction, regardless of quality. */
  vetoed: boolean;
  pass: boolean;
  /** Why it failed, in the writer's terms — also the rewrite instruction. */
  reasons: string[];
  /**
   * What a retry should fix. `null` when nothing needs fixing. Substance,
   * voice, facts, and preferences are separable repairs.
   */
  rewriteKind: RewriteKind | null;
}

export type RewriteKind =
  | "constraint"
  | "accuracy"
  | "substance"
  | "voice"
  | "facts"
  | "preference"
  | "both";

export interface NoteGateThresholds {
  /** Mean quality a note must reach. */
  minOverall: number;
  /** A single dimension this low sinks the note even if the mean is fine. */
  minDimension: number;
  /**
   * Veto above this probability of breaking a constraint. Not 0.5: a Noul at
   * 0.5 means *genuinely uncertain*, and discarding a note on a coin flip
   * throws away good advice. Err toward showing it and letting the writer
   * judge, because they are the one who wrote the constraint.
   */
  maxViolationRisk: number;
  /**
   * Below this, the note is worth re-asking in voice. Set lower than
   * `minDimension`: a note only mildly out of character is not worth a
   * frontier call, and chasing perfect mimicry produces pastiche.
   */
  minAdherence: number;
  /** Treat a misquotation of the passage as disqualifying above this risk. */
  maxQuoteRisk: number;
  /** Treat a declared avoidance as broken above this probability. */

