                observability: {
                  anonymousId: posthogIdentity.anonymousId,
                  sessionId: posthogIdentity.sessionId,
                  folioId: activeFolioId,
                  editorialActionId: "convene-room",
                },
              })) as typeof result;
            } finally {
              unsubscribe();
