234	export function readEditorialPolicyAssessment(
235	  answers: Record<string, SystemOneAnswer>,
236	): EditorialPolicyAssessment {
237	  const checks = EDITORIAL_POLICY_RULES.map((rule) => {
238	    const answer = answers[rule.id];
239	    const probability = isNoul(answer) ? answer.noul : null;
240	    return {
241	      id: rule.id,
242	      source: rule.source,
243	      severity: rule.severity,
244	      status: policyStatus(probability),
245	      probability,
246	      repair: rule.repair,
247	    } satisfies EditorialPolicyCheck;
248	  });
249	  const failed = checks.filter((check) => check.status === "fail");
250	  const uncertain = checks.filter((check) => check.status === "unknown");
251	  const status: EditorialPolicyStatus = failed.length
252	    ? "fail"
253	    : uncertain.length
254	      ? "unknown"
255	      : "pass";
256	
257	  return {
258	    version: EDITORIAL_POLICY_VERSION,
259	    status,
260	    checks,
261	    failed,
262	    uncertain,
263	  };
