1645	/**
1646	 * Run the full editorial board in parallel — convene the room. Each
1647	 * persona reads the same brief + draft and returns a single note. The
1648	 * caller is expected to choose anchor sentences client-side and pass
1649	 * them in `anchors[personaId]`. Falls back to the local generator for
1650	 * any persona whose LLM call fails.
1651	 */
1652	export const conveneRoom = action({
1653	  args: {
1654	    responseLocale: responseLocaleValidator,
1655	    personas: v.array(personaValidator),
1656	    brief: briefValidator,
1657	    draftText: v.string(),
1658	    writerProfile: writerProfileValidator,
1659	    anchors: v.optional(v.record(v.string(), v.string())),
1660	    /** Passages written since the room last read — the background pass. */
1661	    newMaterial: v.optional(v.string()),
1662	    /** Prose digest of how the draft has been moving. */
1663	    trajectory: v.optional(v.string()),
1664	    observability: v.optional(
1665	      v.object({
1666	        anonymousId: v.optional(v.string()),
1667	        sessionId: v.optional(v.string()),
1668	        folioId: v.optional(v.string()),
1669	        editorialActionId: v.optional(v.string()),
1670	      }),
1671	    ),
1672	    // Present when the panel is watching. Each editor then fills their own
1673	    // card as they write, rather than five notes appearing at once at the end.
1674	    streamId: v.optional(v.string()),
1675	  },
1676	  handler: async (ctx, args) => {
1677	    const identity = await ctx.auth.getUserIdentity();
1678	    if (!identity) throw applicationError("authentication_required");
1679	    // Rate limit: convene fans out to one LLM call per persona, making it
1680	    // one of the most expensive endpoints.
1681	    await consumeRateLimit(ctx, {
1682	      action: "agent:room",
1683	      identifier: identity.tokenIdentifier,
1684	      ...RATE_LIMITS.agentRoom,
1685	    });
1686	    const brief = (args.brief ?? null) as ProjectBrief | null;
1687	    const short = countWords(args.draftText) < MIN_EDITOR_WORDS;
1688	    const provider = short
1689	      ? null
1690	      : await pickProvider(ctx, "convene-room", "balanced");
1691	    if (short) {
1692	      throw applicationError("validation_failed", {
1693	        message: "Write a little more before convening the room.",
1694	      });
1695	    }
1696	    if (!provider) {
1697	      throw applicationError("provider_unavailable", {
1698	        recovery: "open_settings",
1699	      });
1700	    }
1701	
1702	    const tasks = args.personas.map(async (pRaw) => {
1703	      const persona = pRaw as AgentPersona;
1704	      const anchor = args.anchors?.[persona.id];
1705	      const req: AgentRequest = {
1706	        responseLocale: args.responseLocale,
1707	        persona,
1708	        brief,
1709	        draftText: args.draftText,
1710	        writerProfile: args.writerProfile,
1711	        anchor,
1712	        instruction: "feedback",
1713	        newMaterial: args.newMaterial,
1714	        trajectory: args.trajectory,
1715	      };
1716	      try {
1717	        // A background pass reads only the new material, so it needs far
1718	        // fewer tokens than a full convene — and should cost less too.
1719	        return await runLlm(
1720	          ctx,
1721	          identity.tokenIdentifier,
1722	          provider,
1723	          req,
1724	          "persona-feedback",
1725	          NO_OUTPUT_CEILING,
1726	          { ...args.observability, distinctId: identity.tokenIdentifier },
1727	          args.streamId
1728	            ? {
1729	                ctx,
1730	                userId: identity.subject || identity.tokenIdentifier,
1731	                streamId: args.streamId,
1732	                personaId: persona.id,
1733	              }
1734	            : undefined,
1735	        );
1736	      } catch (err) {
1737	        throw reportedApplicationError(
1738	          "agents.convene-room",
1739	          "provider_unavailable",
1740	          err,
1741	          { recovery: "retry" },
1742	          {
1743	            provider: provider.label,
1744	            model: provider.modelId,
1745	          },
1746	        );
1747	      }
1748	    });
1749	
1750	    const results = await Promise.all(tasks);
1751	    return results.map((r, i) => ({
1752	      personaId: args.personas[i].id,
1753	      ...r,
1754	    }));
1755	  },
1756	});
