 33	    note: input.note.slice(0, 8000),
 34	    quote: input.quote || input.draft.slice(0, 16_000),
 35	    draftExcerpt: input.draft.slice(0, 24_000),
 36	    brief: input.brief,
 37	    persona: input.persona ? JSON.stringify(input.persona) : undefined,
 38	    writerProfile: input.profile,
 39	  });
 40	  const policyState = buildEditorialPolicyState({
 41	    note: input.note,
 42	    quote: input.quote,
 43	    draft: input.draft,
 44	    persona: input.persona,
 45	    brief: input.brief,
 46	    profile: input.profile,
 47	    operation: input.operation,
 48	    userMessage: input.userMessage,
 49	  });
 50	  const questions = {
 51	    ...buildNoteQuestions({
 52	      hasConstraints: !!state.constraints,
 53	      hasPersonaVoice: !!input.persona?.voice,
 54	      hasAvoidances: !!input.persona?.avoidances?.length,
 55	      hasWriterFacts: !!state.writerFacts,
 56	      hasFeedbackPreferences: !!state.feedbackPreferences,
 57	    }),
 58	    ...buildEditorialPolicyQuestions(),
 59	  };
 60	  // An unanchored note cannot honestly be checked for misquoting a particular passage.
 61	  if (!input.quote || !input.draft.includes(input.quote))
 62	    delete questions.misquotesPassage;
 63	  try {
 64	    const result = await call({
 65	      state: { ...state, ...policyState },
 66	      questions,
 67	    });
 68	    if (
 69	      !result.ok ||
 70	      !result.answers ||
 71	      Object.entries(questions).some(
 72	        ([id, question]) =>
 73	          (result.answers?.[id] as SystemOneAnswer | undefined)?.type !==
 74	          question.type,
 75	      )
 76	    )
 77	      return null;
 78	    const answers = result.answers as Record<string, SystemOneAnswer>;
 79	    return applyEditorialPolicy(
 80	      readNoteVerdict(answers),
 81	      readEditorialPolicyAssessment(answers),
 82	    );
 83	  } catch {
 84	    return null;
 85	  }
