 536	    traceId: usageTraceId,
 537	    editorialActionId: observability?.editorialActionId,
 538	    folioId: observability?.folioId,
 539	  };
 540	
 541	  try {
 542	    const generation = {
 543	      model: provider.model,
 544	      system,
 545	      prompt: user,
