1673	    // card as they write, rather than five notes appearing at once at the end.
1674	    streamId: v.optional(v.string()),
1675	  },
1676	  handler: async (ctx, args) => {
1677	    const identity = await ctx.auth.getUserIdentity();
1678	    if (!identity) throw applicationError("authentication_required");
1679	    // Rate limit: convene fans out to one LLM call per persona, making it
1680	    // one of the most expensive endpoints.
