1693	        message: "Write a little more before convening the room.",
1694	      });
1695	    }
1696	    if (!provider) {
1697	      throw applicationError("provider_unavailable", {
1698	        recovery: "open_settings",
1699	      });
1700	    }
1701	
1702	    const tasks = args.personas.map(async (pRaw) => {
1703	      const persona = pRaw as AgentPersona;
1704	      const anchor = args.anchors?.[persona.id];
1705	      const req: AgentRequest = {
1706	        responseLocale: args.responseLocale,
1707	        persona,
1708	        brief,
1709	        draftText: args.draftText,
1710	        writerProfile: args.writerProfile,
1711	        anchor,
1712	        instruction: "feedback",
1713	        newMaterial: args.newMaterial,
1714	        trajectory: args.trajectory,
1715	      };
1716	      try {
1717	        // A background pass reads only the new material, so it needs far
1718	        // fewer tokens than a full convene — and should cost less too.
1719	        return await runLlm(
1720	          ctx,
1721	          identity.tokenIdentifier,
1722	          provider,
1723	          req,
1724	          "persona-feedback",
1725	          NO_OUTPUT_CEILING,
1726	          { ...args.observability, distinctId: identity.tokenIdentifier },
1727	          args.streamId
1728	            ? {
1729	                ctx,
1730	                userId: identity.subject || identity.tokenIdentifier,
1731	                streamId: args.streamId,
1732	                personaId: persona.id,
1733	              }
1734	            : undefined,
1735	        );
1736	      } catch (err) {
1737	        throw reportedApplicationError(
1738	          "agents.convene-room",
1739	          "provider_unavailable",
1740	          err,
1741	          { recovery: "retry" },
1742	          {
1743	            provider: provider.label,
1744	            model: provider.modelId,
1745	          },
1746	        );
1747	      }
1748	    });
1749	
1750	    const results = await Promise.all(tasks);
1751	    return results.map((r, i) => ({
1752	      personaId: args.personas[i].id,
1753	      ...r,
1754	    }));
1755	  },
1756	});
