1718	        // fewer tokens than a full convene — and should cost less too.
1719	        return await runLlm(
1720	          ctx,
1721	          identity.tokenIdentifier,
1722	          provider,
1723	          req,
1724	          "persona-feedback",
1725	          NO_OUTPUT_CEILING,
1726	          { ...args.observability, distinctId: identity.tokenIdentifier },
1727	          args.streamId
1728	            ? {
1729	                ctx,
1730	                userId: identity.subject || identity.tokenIdentifier,
1731	                streamId: args.streamId,
1732	                personaId: persona.id,
1733	              }
1734	            : undefined,
1735	        );
1736	      } catch (err) {
1737	        throw reportedApplicationError(
1738	          "agents.convene-room",
