/**
 * The room of editors — system prompt builder and the local fallback
 * generator. The Convex action in `convex/agents.ts` calls into this module
 * when no remote provider is configured, or when the configured provider
 * fails. The prompt builder is also reused by the LLM-backed code path so
 * the voices stay consistent across providers.
 *
 * Intentionally no `"use node";` directive: this file is pure string
 * assembly with no Node.js built-ins, and it is also imported by the
 * Vite-bundled client code in `src/utils/{ai-client,ai-orchestrator}.ts`.
 * The Node runtime is opted into at the action boundary in
 * `convex/agents.ts`, which is the only file that needs it.
 */
import type { Persona, ProjectBrief, WriterProfile } from "../src/types";
import { firstSubstantiveSentence } from "./agentTools";
import { probeSummaryLine } from "../src/utils/dossier-probes";
import { prompt as renderNamed } from "../src/utils/prompts";

export type FeedbackType =
  | "encouragement"
  | "suggestion"
  | "critique"
  | "perspective";

export interface AgentPersona {
  id: string;
  name: string;
  role: string;
  description: string;
  focus: string;
  /** Short fictional history for role play and continuity. */
  backstory?: string;
  /** The editor's specific theory and method of criticism. */
  criticalMethod?: string;
  /** Rich voice spec — distinct diction/rhythm/signature for this editor. */
  voice?: string;
  /** Recurring rhetorical habits that make the editor recognizable. */
  signatureMoves?: string[];
  /** Language and behaviors this editor must not borrow from the others. */
  avoidances?: string[];
  /** A few sample lines in this persona's voice, used as light few-shot. */
  sampleLines?: string[];
  /** Optional per-persona generation prefs (honored on the BYOK client path). */
  providerId?: string;
  model?: string;
  temperature?: number;
  /** Optional colour from the persona object; not used by the LLM prompt. */
  color?: string;
  icon?: string;
}

export interface AgentRequest {
  responseLocale?: import("../src/i18n/locale").AppLocale;
  persona: AgentPersona;
  brief: ProjectBrief | null;
  draftText: string;
  /** Private writer context, kept separate from the folio's project brief. */
  writerProfile?: WriterProfile;
  /** Anchor sentence the note should pin to, if known. */
  anchor?: string;
  /** Prior conversation for follow-up turns. */
  priorMessages?: Array<{ author: "user" | "persona"; text: string }>;
  /** The user's follow-up question, if this is a reply. */
  userMessage?: string;
  /**
   * Prose summary of how the draft has been moving — paragraphs added and
   * cut, net words, the most recent new material. Lets an editor respond to
   * the writer's direction rather than to a cold snapshot.
   */
  trajectory?: string;
  /**
   * The passages written since this editor last read. When present the note
   * should be aimed here, with the full draft as context rather than subject.
   */
  newMaterial?: string;
  /** Direct instruction the user is asking the persona to act on. */
  instruction?:
    | "feedback"
    | "elaborate"
    | "riff"
    | "rewrite-suggestion"
    | "analyze";
}

export interface AgentResponse {
  text: string;
  type: FeedbackType;
  provider: "rivet" | "anthropic" | "openai" | "portkey" | "local";
  /** Stable handle shared by PostHog feedback and the generation event. */
  traceId?: string;
  /** Soft signal of how confident the model is in the answer (0-1). */
  confidence?: number;
  /**
   * Exact draft passage the note pins to. Populated from the `quote_passage`
   * tool call (or deterministically for the local fallback) rather than
   * scraped from the reply text.
   */
  anchor?: string;
}

/* ── Prompt construction ────────────────────────────────────────── */

/**
 * The per-persona "how you write" block. This is what makes the five editors
 * sound like genuinely different people rather than one writer in five hats.
 * Falls back to nothing when a persona has no voice spec (older saved casts).
 */
function buildVoiceBlock(persona: AgentPersona): string {
  if (
    !persona.backstory &&
    !persona.criticalMethod &&
    !persona.voice &&
    (!persona.signatureMoves || persona.signatureMoves.length === 0) &&
    (!persona.avoidances || persona.avoidances.length === 0) &&
    (!persona.sampleLines || persona.sampleLines.length === 0)
  ) {
    return "\nSpeak in your own voice. Do not sound like the other editors.\n";
  }
  const lines: string[] = [
    "\nPERSONA BIBLE (binding for every note, reply, rewrite, analysis, and judgment):",
  ];
  if (persona.backstory) {
    lines.push(
      `BACKSTORY (internalize it; mention it only when it naturally matters):\n${persona.backstory}`,
    );
  }
  if (persona.criticalMethod) {
    lines.push(`EDITORIAL DOCTRINE:\n${persona.criticalMethod}`);
  }
  if (persona.voice) lines.push(`VOICEPRINT:\n${persona.voice}`);
  if (persona.signatureMoves && persona.signatureMoves.length > 0) {
    lines.push(
      `SIGNATURE MOVES (use one or two when natural, not all mechanically):\n${persona.signatureMoves
        .map((move) => `- ${move}`)
        .join("\n")}`,
    );
  }
  if (persona.avoidances && persona.avoidances.length > 0) {
    lines.push(
      `NEVER BORROW THESE HABITS:\n${persona.avoidances
        .map((avoidance) => `- ${avoidance}`)
        .join("\n")}`,
    );
  }
  if (persona.sampleLines && persona.sampleLines.length > 0) {
    lines.push(
      `Lines in your register, for calibration (do not reuse them verbatim):\n${persona.sampleLines
        .map((l) => `  — ${l}`)
        .join("\n")}`,
    );
  }
  return `${lines.join("\n")}\n`;
}

/**
 * The persona layer answers who this editor is. Operational behaviour lives
 * in `editorial-protocol.md` so identity and rules can evolve independently.
 */
export function buildPersonaPrompt(persona: AgentPersona): string {
  return renderNamed("persona-system", {
    personaName: persona.name,
    personaRole: persona.role,
    personaDescription: persona.description,
    personaFocus: persona.focus,
    voice: buildVoiceBlock(persona),
  });
}

/**
 * The full system prompt a writer can preview on the /personas page. Shared so
 * the preview never drifts from what the editor is actually told.
 */
export function buildVoicePreview(persona: AgentPersona): string {
  return buildSystemPrompt(persona);
}

export function buildSystemPrompt(persona: AgentPersona): string {
  return [buildPersonaPrompt(persona), renderNamed("editorial-protocol")]
    .join("\n\n")
    .replace(/\n{3,}/g, "\n\n");
}

export function buildUserPrompt(req: AgentRequest): string {
  const brief = req.brief;
  const briefBlock = brief
    ? `PROJECT BRIEF (verbatim, do not invent new facts)
- Title: ${brief.answers.workingTitle}
- Format: ${brief.answers.format}
- Audience: ${brief.answers.audience}
- Goal: ${brief.answers.goal}
- Tone: ${brief.answers.tone}
- Constraints: ${brief.answers.constraints}
- Success signal: ${brief.answers.successSignal}

`
    : `PROJECT BRIEF: none filed — the writer is working without a dossier. Read for clarity and intent.\n\n`;

  // Typed follow-ups the writer answered during the interview. These are the
  // commitments they made in a single tap rather than a paragraph, so they are
  // often sharper than the prose fields above and worth stating separately.
  const particularsBlock = probeParticularsBlock(brief);

  const profile = req.writerProfile;
  const profileLines: string[] = [];
  if (profile) {
    profileLines.push(
      profile.displayName.trim()
        ? `- Name: ${profile.displayName.trim()}`
        : "- Name: not supplied",
    );

