          );
        }
      }),
    );

    let synthesis: string;
    try {
      const memoInput: MemoForSynthesis[] = args.personas.map((pRaw, i) => {
        const persona = pRaw as AgentPersona;
        return {
          personaName: persona.name,
          role: persona.role,
          text: memos[i].text,
