        withResponseLanguage(buildSynthesisSystemPrompt(), args.responseLocale),
        buildSynthesisPrompt(memoInput, brief, args.writerProfile),
        NO_OUTPUT_CEILING,
        "persona-analysis:synthesis",
      );

            },
